REPLACE INTO `menus` (`id`, `parent_id`, `lang`, `title`, `full_title`, `slug`, `content`, `image`, `video`, `external_url`, `sort`, `depth`, `is_active`, `show_in_menu`, `legacy_table`, `legacy_id`, `created_at`, `updated_at`) VALUES (1,NULL,'eng','About us','About us','about-us','<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"text-align: start;\"><font size=\"4\" style=\"\" face=\"arial\" color=\"#000000\"><br></font></span></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"text-align: start;\"><font size=\"4\" style=\"\" face=\"arial\" color=\"#000000\">Pedagogical School named after Aman Kekilov was established as the Poltoratsk Pedagogical College in accordance with the order of the People\'s Educational Commissariat of Turkmenistan No. 16 dated March 4, 1922. In 1927, with the return of the former national name to the capital of Turkmenistan, since 1938, the Ashgabat Pedagogical College was renamed to the Ashgabat Pedagogical School. On July 13, 1967, by the Decree of the Presidium of the Supreme Soviet of the USSR, the Pedagogical School of the city of Ashgabat was awarded with the Order of the Red Banner of Labor. On July 24, 1975, by the Resolution of the Council of Ministers of Turkmenistan No. 312, the college was renamed in honor of Aman Kekilov. Aman Kekilov is a scientist and poet who studied and worked as a teacher at this school. By order No. 146 of the Ministry of Education of Turkmenistan dated November 15, 2001, the school was renamed into the Pedagogical School named after Aman Kekilov. In the Year of \"Neutrality and Peace\" – on September 1, 2015, on the occasion of the Day of Knowledge and Student Youth, with the blessing of the President of our country, a new complex of buildings of the Aman Kekilov Pedagogical School was opened and put into operation. The new building complex of the educational school is designed for modern education of students and the creative work of teachers. There are 7 methodological associations in the pedagogical school, according to which teachers, on the basis of curricula, teach students modern and in-depth pedagogical teaching skills. The Assembly Hall for 300 seats, located in the educational building, provides opportunities for various conferences and meetings. Students are provided with a recording studio, computer labs, a language room, and pedagogical multimedia equipment. In addition, the educational building has rooms for sewing, handicraft and cooking, four music rooms and three halls of fine arts. The combination of preschool and school psychology methods also contributes to a more developed understanding of the teaching career. In the educational and academic building is situated a large library for students with a huge amount of books and teaching-related data. The museum, located on the first floor of the building, allows students and guests to learn about the history, achievements and work of our school. Also in the educational and academic building is situated a medical office. In two dormitories of the new building complex of the pedagogical school, all conditions have been created for students to live. The hostel has a dining room with 400 seats. Also, on the territory of the hostel there is an indoor gym for 200 spectators, which also allows you to engage in various sports. In the open-air sports complex, students can play football, volleyball, basketball, tennis and other sports.</font></span><br></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"text-align: start;\"><font size=\"4\" style=\"\" face=\"arial\" color=\"#000000\"><br></font></span></p>',NULL,NULL,NULL,1,1,1,1,'menu_yokarky',2,'2026-10-28 11:40:34','2026-10-28 11:40:34'),(2,NULL,'rus','О нас','О нас','o-nas','<p class=\"MsoNormal\" style=\"text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"text-align: start;\"><br></span></font></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"text-align: start;\">Педагогическая школа имени Амана Кекилова создано как Полторацкий педагогический колледж в соответствии с приказом Народного Образовательного комиссариата Туркменистана № 16 от 4 марта 1922 года. Он в 1927 году, с возвращением столице Туркменистана бывшего национального названия, начиная с 1938 года Ашхабадский педагогический техникум был переименован в Ашхабадский педагогическое училище.&nbsp; 13 июля 1967 года Указом Президиума Верховного Совета СССР Педагогическое училище города Ашхабада был награжден орденом Трудового Красного Знамени. 24 июля 1975 года Постановлением Совета Министров Туркменистана № 312, колледж был переименован в честь Аман Кекилова. Аман Кекилов - ученый и поэт, который учился и работал учителем в этой школе. Приказом № 146 Министерства образования Туркменистана от 15 ноября 2001 года училище было переименовано в Педагогическую школу имени Амана Кекилова. В Год «Нейтралитета и мира» - 1 сентября 2015 года, по случаю Дня знаний и студенческой молодежи, по благословению Президента нашей страны был открыт и сдан в эксплуатацию новый комплекс корпусов Педагогической школы имени Амана Кекилова. Новый строительный комплекс учебной школы рассчитан на современное обучение студентов и творческую работу преподавателей. В педагогической имеются школе 7 методических объединений, по которым учителя на основе учебных программ обучают студенческую молодежь современным и углубленным педагогическим навыкам обучения. В актовом</span><b style=\"font-weight: bold; text-align: start;\">&nbsp;</b><span style=\"text-align: start;\">Зале на 300 мест, расположенном в учебном корпусе, имеются возможности для проведения различных конференц и встреч. Студенты обеспечены студией звукозаписи, компьютерными классами, языковым кабинетом, а также педагогическим мультимедийным оборудованием. Кроме того, в учебном корпусе имеется комнаты для шитья, рукоделия и приготовления пищи, четыре музыкальных кабинета и три зала изобразительного искусства. Сочетание методов психологии дошкольного и школьного обучения также способствует более развитому пониманию педагогической карьеры. В учебном и академическом корпусе находится большая библиотека для студентов с огромным количеством книг и данных, связанных с преподаванием.&nbsp; Музей, расположенный на первом этаже здания, позволяет ученикам и гостям познакомиться с историей, достижениями и работой нашей школы. Также в учебном и академическом корпусе имеется медицинский кабинет. В двух общежитиях нового строительного комплекса педагогической школы созданы все условия для проживания учеников. В общежитии есть столовая на 400 мест. Также, на территории общежития расположен крытый тренажерный зал на 200 зрителей, который также позволяет заниматься различными видами спорта. В спорткомплексе под открытым небом студенты могут заниматься футболом, волейболом, баскетболом, теннисом и другими видами спорта.</span></font><br></p><p class=\"MsoNormal\" style=\"text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"text-align: start;\"><br></span></font></p>',NULL,NULL,NULL,1,1,1,1,'menu_yokarky',4,'2026-10-28 11:40:34','2026-10-28 11:40:34'),(3,NULL,'tm','HÜNÄRLER','Hünärler','hunarler','<br>',NULL,NULL,NULL,2,1,1,1,'menu_yokarky',14,'2026-10-28 11:40:34','2026-10-28 11:40:34'),(4,NULL,'eng','FACULTIES','Faculties','faculties','<br>',NULL,NULL,NULL,2,1,1,1,'menu_yokarky',15,'2026-10-28 11:40:34','2026-10-28 11:40:34'),(5,NULL,'rus','Специальности','Специальности','spetsialnosti','<br>',NULL,NULL,NULL,2,1,1,1,'menu_yokarky',16,'2026-10-28 11:40:34','2026-10-28 11:40:34'),(6,NULL,'tm','RESMINAMALAR','Resminamalar','resminamalar','SAÇLY DURSUNOWA ADYNDAKY ARKADAG SÄHER\r\nLUKMANÇYLYK ORTA HÜNÄR OKUW MEKDEBI\r\n2025/2026-njy okuw ýyly üçin aşakdaky\r\nhünärler boyunça talyplyga kabul edýär:\r\n\r\n \r\nByujet esasynda:\r\n1.	Şepagatçylyk işi\r\n2.	Laboratoriýa anyklaýyş işi\r\n3.	Bejeriş işi.\r\n4.	Saglygy goraýyş-öňüni alyş işi.\r\n5.	Farmasiýa\r\nSaçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebine Arkadag şäherinde we Ahal welaýatynda hemişelik ýaşaýan, umumy orta bilimden pes bolmadyk binýatda bilimi bolan, ýaşy 35-den geçmedik Türkmenistanyň rayatlary giriş sy- naglarynyň netijeleri boyunça bäsleşik esa¬synda okuwa kabul ediyär.\r\nResmi iş kagyzlary: Arkadag şäherinde (Arkadag şaheri we Ahal welaýaty boýunça 2025-nji yytyň 14 — 27-np iyuly aralygynda kabul edilýar.\r\nResmi iş kagyzlarynyň sanawy:\r\n— bellenilen nusgada direktoryň adyna ýazylan arza,\r\n—	bellenilen nusgadaky sowalnama \r\n(anketa).\r\n—	bilimi baradaky resminama (asyl nus- gasy);\r\n—	Türkmenistanyň Saglygy goraýyş we derman senagaty ministrligi tarapyndan bel- lenilen nusgadaky saglyk kepilnamasy;\r\n—	soňky okan ýerinden (işlän ýerinden, harbv bölümden) häsiýetnama;\r\n—	3x4 sm ölçegdäki sekiz sany fotosurat;\r\n—	işleyänler üçin zähmet depderçesiniň tassyklanan göçürmesi:\r\n— okuw dersleri boýunça mekdep okuw- çylarynyň döwtet bäsleşiginiň ýeňijileri. halkara bäsleşiklere gatnaşan Türkmenistanyň ýygyndy toparynyň agzalary şol ýagdaýlary tassykaýan degişli resminamanyň asyl nusgasyny tabşyryar.\r\nBulardan başga-da. okuwa girmäge isteg bildirýänler ýokarda görkezilen resminamalar bilen birlikde. resminamalary kabul edyän iş toparyna aşakdakylary görkezyärler we nus- galaryny tabşyrýarlar.\r\n— pasportyny.\r\n— harby şahadatnamasyny ya-da harby hasaba goylandygy hakynda şahadatnama- syny.\r\nDalaşgär bäsleşiksiz we (ya-da) okuwa kabul edilmek üçin artykmaç hukukdan peý- dalanýandygyny tassyklaýan beýleki resmi-namalary görkezip biler.\r\nNädogry berilen maglumatlar we galp res¬mi iş kagyzlary üçin dalaşgär şahsy jogap-kärçilik çekyär.\r\nGiriş synaglary we okuwa kabul edilmek Saçty Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde (Arkadag ş.) 2025-nji yylyň iýul ayynyň 30-31-i, awgust ayynyň 2-3-i we 5-i günlerinde geçirilyär.\r\nGiriş synaglary ähli hunärler boýunça himiya, bioiogiya. Türkmenislanyň taryhy derslerinden geçirilyär.\r\nOkuw dersleri boyunça giriş synaglary Türkmenistanyň orta mekdepleriniň okuw maksatnamalarynyň esasynda. döwlet dilin¬de dilden geçirilyär\r\nSaýlap alan hünärine durnuklydygyny kesgittemek maksady bilen, dalaşgärler pa- tologoanatomik edaranyň işi bilen tanyşdyrylar.\r\nGiriş synaglarynyň teribinde bellenilen wagtda synaglara esassyz sebäplere görä gelip bimedikler ýa-da okuw dersleriniň biri boýunça synagdan geçip bilmedikler soňky synaglara göýberilmeyar\r\nGiriş synaglaryndan üstünlikli geçen ýag- daýynda, bäsleşiksiz we talyplyga kabul edilmek üçin artykmaç hukukdan «Bilim hakynda» Türkmenistanyň Kanunynyň rejelenen gönüşinde kesgitlenen düzgünlere laýyk gelýän dalaşgärler peýdalanýarlar\r\nSaçly Dursunowa adyndaky\r\nArkadag şäher lukmançylyk orta\r\nhünär okuw mekdebiniň salgysy:\r\nArkadag şäheri,\r\nArkadag şaýoly. 22,\r\ntel.: 57-20-21. 57-20-22.\r\n',NULL,NULL,NULL,3,1,1,1,'menu_yokarky',17,'2026-10-28 11:40:34','2026-10-28 11:40:34'),(7,NULL,'eng','DOCUMENTS','Documents','documents','<br>',NULL,NULL,NULL,3,1,1,1,'menu_yokarky',18,'2026-10-28 11:40:34','2026-10-28 11:40:34'),(8,NULL,'rus','ДОКУМЕНТАЦИЯ','Документация','dokumentatsiya','<br>',NULL,NULL,NULL,3,1,1,1,'menu_yokarky',19,'2026-10-28 11:40:35','2026-10-28 11:40:35'),(9,NULL,'tm','TALYP DURMUŞY','Talyp durmuşy','talyp-durmushy','<h3 style=\"line-height: 1.1; font-family: Arial, Helvetica, sans-serif; outline: none; margin-bottom: 10px; font-size: 24px; color: rgb(0, 0, 0);\"><br></h3><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde talyplar bilen işjeň terbiýeçilik işi alnyp barylýar, onuň maksady häzirki zaman maglumat giňişligine uýgunlaşan, öz ýurdunyň raýaty, ösen, bitewi şahsyýeti kemala getirmekden ybaratdyr.&nbsp;<img src=\"https://tdbgi.edu.tm/images/Institut_barada_img/Talypgyz.jpg\" class=\"picture-margin-right picture-thumbnial\" width=\"300px\" alt=\"BasBina\" style=\"line-height: 21px; outline: none; border: 1px solid rgb(221, 221, 221); float: right; margin: 8px 0px 8px 8px; display: inline-block; max-width: 100%; padding: 4px; border-radius: 4px; height: auto; overflow: hidden;\">Talyplaryň ylmy, döredijilik ukyplaryny we sagdyn durmuş ýörelgesini ösdürmek üçin işler hem alnyp barylýar.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Institutda Talyplaryň ylmy jemgyýeti işjeň hereket edýär. Talyplaryň ylmy konferensiýalary her ýyl, şol sanda daşary ýurt dilinde geçirilýär. Talyplarymyz dürli derejedäki degişli hünärler boýunça ylmy we amaly konferensiýalara, olimpiadalara gatnaşýarlar. Ylmy maslahatyň netijelerine esaslanyp, Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde&nbsp;talyplaryň ylmy işleriniň ýygyndylaryny neşir edýär. Ýokary kursyň talyplary ýörite orta okuw mekdepleriniň arasynda geçirilýän ylmy we amaly konferensiýalara işjeň gatnaşýarlar, dokladlar we ylmy habarlar bilen çykyş edýärler.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde talyplaryň döwrebap okuwlaryny we sapakdan daşary işlerini, durmuşyny we dynç alşyny guramak üçin zerur şertleriň ählisi döredilendir.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Talyplar okuwdan boş wagtlary edebi-çeper, ylmy döredijilik işleri bilen meşgullanýarlar hem-de olar üçin belli medeniýet we sungat işgärleri bilen döredijilik duşuşyklary gurnalýar. Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde&nbsp;“Bagtyýarlyk Binasy” tans topary işleýär.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Talyplar kluby \"Bilimler we talyp ýaşlar güni\", Täze ýyl gijesi, 8-nji mart we şuňa meňzeşlere bagyşlanan Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiniň&nbsp;derejesinde baýramçylyklary gurnaýar.&nbsp; Zehinli talyplarymyz dürli derejedäki döredijilik ýaşlar festiwallaryna we ýaryşlaryna uly isleg bilen gatnaşýarlar.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Bu topar dürli çärelerde köpçüligiň öňünde çykyş edýär. “Bagtyýarlyk binasy” aýdym-saz topary häzirki zaman we halk aýdymlary bilen öz muşdaklarynyň göwnüni awlamagy başarýar. Bu toparlar ýurdumyz boýunça geçirilýän baýramçylyk dabaralaryna hem işjeň gatnaşýarlar. Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiniň talyplary ýörite orta okuw mekdepleriniň arasynda geçirilýän “Talyp joşguny” we “Talyp gözeli” bäsleşiklerinde işjeň çykyş edýärler.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Talyplary sport bilen meşgullanmaklyga çekmeklik terbiýeçilik işiniň esasy ugurlarynyň biridir.&nbsp;</p><h3 style=\"line-height: 1.1; font-family: Arial, Helvetica, sans-serif; outline: none; margin-bottom: 10px; font-size: 24px; color: rgb(0, 0, 0); text-align: center;\">Talyplaryň umumy ýaşaýyş jaýlary</h3><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Berkarar döwletiň täze eýýamynyň Galkynyşy döwründe hormatly Prezidentimiziň tagallalary bilen talyp ýaşlarymyzyň ýaşaýyş-durmuş şertleriniň hilini ýokarlandyrmak, olaryň okamaklary we okuwdan boş wagtlary medeniýetli dynç almaklaryny üpjün etmek üçin Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde&nbsp;umumy ýaşaýyş jaýlarynda ähli zerur durmuş şertleri döredilendir.&nbsp;<img src=\"https://tdbgi.edu.tm/images/Institut_barada_img/talypd.jpg\" class=\"picture-margin-right picture-thumbnial\" width=\"300px\" alt=\"BasBina\" style=\"line-height: 21px; outline: none; border: 1px solid rgb(221, 221, 221); float: right; margin: 8px 0px 8px 8px; display: inline-block; max-width: 100%; padding: 4px; border-radius: 4px; height: auto; overflow: hidden;\">Häzirki wagtda institutda umumy ýaşaýyş jaýlaryň 3-si bolup, olarda ýörite enjamlaşdyrylan howany ýyladyş we sowadyş ulgamy, aşhana, kir ýuwulýan, tikin, okuw we “Bagtyýarlyk” otaglary bilen üpjün edilendir. “Bagtyýarlyk” otagynda talyplara hormatly Prezidentimiziň kitaplary, döwürleýin neşirler, dünýäde bolup geçýän halkara wakalar bilen içgin tanyşmaga zerur şertler döredilendir.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Her ýyl \"Iň oňat talyp otagy\" we \"Fakultetiň iň gowy umumy ýaşaýyş jaýy\" ýaryşlary geçirilýär. Ýeňijiler diplomlar we gymmatly sowgatlar bilen sylaglanylýar. Ýeňijiler barada maglumat we olaryň suratlary Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde&nbsp;Bilim portalynda we web sahypasynda ýerleşdirilýär.</p><p class=\"text-taryh\" style=\"line-height: 21px; font-family: Arial, Helvetica, sans-serif; outline: none; margin-right: 0px; margin-bottom: 1px; margin-left: 0px; text-indent: 30px; color: rgb(0, 0, 0); font-size: 14px;\">Hormatly Prezidentimizň bilim prosesine sanly bilimi ornaşdyrmak baradaky görkezmelerinden ugur alyp, institutda ähli talyplar we tutuş professor-mugallymlar tarapyndan üstünlikli ulanylýan bilim portaly döredildi. Saçy Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde&nbsp;bilim portalynyň häzirki zamanyň wajyp sanly bilim bermek serişdesi bolmagy bilen baglylykda, onuň umumy ýaşaýyş jaýlarynda-da hem elýeterliligi gazanyldy.</p>',NULL,NULL,NULL,4,1,1,1,'menu_yokarky',20,'2026-10-28 11:40:35','2026-10-28 11:40:35'),(10,NULL,'eng','Student life','Student life','student-life','<br>',NULL,NULL,NULL,4,1,1,1,'menu_yokarky',21,'2026-10-28 11:40:35','2026-10-28 11:40:35'),(11,NULL,'rus','Студенческая жизнь','Студенческая жизнь','studencheskaya-zhizn','<br>',NULL,NULL,NULL,4,1,1,1,'menu_yokarky',22,'2026-10-28 11:40:35','2026-10-28 11:40:35'),(12,NULL,'tm','Biz barada','Biz barada','biz-barada','<div style=\"text-align: justify;\"><h2 class=\"page-content_contentHeaderTitle__u2rK2\" style=\"margin: 15px auto 25px; text-align: center; line-height: 32px; max-width: 90%; font-size: 24px; font-family: Inter, sans-serif; white-space-collapse: preserve-breaks;\">Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebi</h2><div class=\"page-content_pageContent__aacCE\" style=\"word-break: break-word; color: rgb(22, 22, 22); font-family: Inter, sans-serif; font-size: medium; text-align: start; white-space-collapse: preserve-breaks;\"><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; text-align: justify; font-size: 16px;\">Ýurdumyzda milli saglyk ulgamyny ösdürmekde we kämilleşdirmekde hünärine ezber saglygy goraýyş işgärlerini kemala getirmek wezipesine ýokary ähmiýet berilýär. Arkadag şäherinde gurulan saglygy goraýyş edaralaryny orta hünär bilimli işgärler bilen doly üpjün etmek maksady bilen, ýöriteleşdirilen bilim edarasyny döretmek baradaky başlangyjy türkmen halkynyň Milli Lideri, Gahryman Arkadagymyzyň beýan edendigi mälimdir. Lukman Arkadagymyzyň elmydama halkyň saglygyny goramak, milli saglyk ulgamyny ösdürmek barada taýsyz tagallalary edýändigini ýeri gelende buýsanç bilen bellemek örän ýerliklidir. Hormatly Prezidentimiz Serdar Berdimuhamedow 2023-nji ýylyň fewralynda lukmançylyk orta hünär okuw mekdebini döretmek baradaky Karara gol çekdi. Bu lukmançylyk orta hünär okuw mekdebine 2023-nji ýylyň mart aýynda Türkmenistanyň Mejlisiniň karary bilen zenan lukman&nbsp;Saçly Dursunowanyň ady dakyldy.&nbsp;<a target=\"_blank\" href=\"https://saglykhm.gov.tm/merdana-zenan-ussat-lukman-sacly-dursunowa\" alt=\"Saçly Dursunowanyň\" style=\"text-decoration-skip-ink: auto; transition: var(--transition); color: var(--primary-color) !important;\">Saçly Dursunowa</a>&nbsp;«lukmançylyk ylymlarynyň kandidaty» we «lukmançylyk ylymlarynyň doktory» diýen alymlyk derejeleriniň eýesidir. Ömrüni mähriban halkyna we Watanyna bagyşlan merdana türkmen zenanynyň zähmet ýoly ýaşlar üçin görelde mekdebidir. Lukmançylyk ýörite orta mekdepde alym-lukman, birnäçe döwlet baýraklarynyň eýesi, frontçy, harby lukman Saçly Dursunowanyň ýeňil bolmadyk durmuş we zähmet ýoly, ylmy işi baradaky dokumental materiallar jemlenen muzeý hem döredilen.&nbsp;&nbsp;</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; text-align: justify; line-height: 0.5; font-size: 16px;\">​</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; text-align: justify; font-size: 16px;\">Täze bilim edarasynyň binalar toplumynyň düzümi esasy bina, sport meýdançalaryndan, dynç alyş zolaklary hem-de ähli amatlyklary bolan umumy ýaşaýyş jaýyndan ybaratdyr. Okuw otaglarynda saýlanyp alnan hünäriň we binýatlaýyn lukmançylyk ylymlarynyň — biologiýanyň, anatomiýanyň hem-de fiziologiýanyň esaslaryny çuňlaşdyryp öwrenmäge ähli döwrebap şertler döredilen. Umumy sapak otaglary, tejribe sapaklaryny geçmek üçin niýetlenen barlaghanalar häzirki zaman multimediýa we innowasion enjamlar bilen üpjün edilen. Bu ýerdäki bilimleriň çeşmesi bolan kitaplary özünde jemleýän elektron kitaphananyň gaznasynda ýerleşdirilen köp sanly ýörite okuw we okuw-usulyýet kitaplary bilen birlikde, türkmen halkynyň Milli Lideri Gurbanguly Berdimuhamedowyň ylmy-barlag işleri hem-de monografiýalary mugallymlardyr talyplara möhüm gollanma bolup hyzmat eder.</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; text-align: justify; line-height: 0.5; font-size: 16px;\">​<br></p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; text-align: justify; font-size: 16px;\">Mekdebiň otaglarynda ornaşdyrylan häzirki zaman interaktiw tagtalarynyň kömegi arkaly sapaklary innowasion usulynda geçirmek üçin giň şertler döredilendir. Wideosapaklaryň kömegi bilen Türkmenistanyň baý tebigatyna gaýybana syýahat etmek, dermanlyk ösümlikleri, olaryň gurluşyny, ösüş aýratynlyklaryny öwrenmek mümkinçilikleri bar. Simulýasiýa otaglarynda ornaşdyrylan enjamlar arkaly talyplaryň sanjymlaryň dürli görnüşlerini ýerine ýetirmegi, arterial gan basyşyny ölçemegi, ýürek we dem alyş ulgamlarynyň reanimasiýa çärelerini geçirmek arkaly ilkinji lukmançylyk kömegini bermek usullaryny öwrenmegi, olar üçin netijeli tejribe okuwydyr. Türkmen halkynyň Milli Lideri, ýurdumyzyň Ylymlar akademiýasynyň akademigi, lukmançylyk ylymlarynyň doktory, professor Gurbanguly Berdimuhamedowyň «Türkmenistanyň dermanlyk ösümlikleri» atly köp jiltli ylmy-ensiklopedik eseri bolsa, bu ugurda iň gowy gollanmadyr.</p></div></div>',NULL,NULL,NULL,1,1,1,1,'menu_yokarky',23,'2026-10-28 11:40:35','2026-10-28 11:40:35'),(13,NULL,'tm','Moodle','Sanly bilim portaly','sanly-bilim-portaly','<span style=\"font-size: 14.08px;\">Mekdebi[ sanly bilim portaly</span><div><span style=\"font-size: 14.08px;\"><br></span></div><div><span style=\"font-size: 14.08px;\">https://119.235.119.206/</span></div>',NULL,NULL,'http://119.235.119.206/',4999,1,1,1,'menu_yokarky',24,'2026-10-28 11:40:35','2026-10-28 11:40:35'),(14,3,'tm','Şepagatçylyk işi','Şepagatçylyk işi','shepagatchylyk-ishi','<div open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\" style=\"color: rgb(119, 119, 119); font-family: \" 14px;\"=\"\"><span style=\"font-weight: 700 !important;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Ugur:&nbsp;<span style=\"white-space: pre;\">			</span>&nbsp; &nbsp; &nbsp; &nbsp; Şepagatçylyk işi.</font></span></div><div open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\" style=\"color: rgb(119, 119, 119); font-family: \" 14px;\"=\"\"><span style=\"font-weight: 700 !important;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Hünär:<span style=\"white-space: pre;\">			</span>&nbsp; &nbsp; &nbsp; &nbsp; Şepagatçylyk işi</font></span></div><div open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\" style=\"color: rgb(119, 119, 119); font-family: \" 14px;\"=\"\"><span style=\"font-weight: 700 !important;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Okuwyň möhleti:<span style=\"white-space: pre;\">		</span>2 ýyl 6 aý</font></span></div><div open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\" style=\"color: rgb(119, 119, 119); font-family: \" 14px;\"=\"\"><span style=\"font-weight: 700 !important;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Kär:<span style=\"white-space: pre;\">				</span>&nbsp; &nbsp; &nbsp; &nbsp; Umumy tejribeli şepagat uýasy.</font></span></div><div open=\"\" sans\",=\"\" arial,=\"\"