REPLACE INTO `news` (`id`, `lang`, `title`, `slug`, `excerpt`, `content`, `image`, `video`, `published_at`, `is_published`, `views`, `legacy_id`, `created_at`, `updated_at`) VALUES (1,'tm','Jemgyýetçilik saglygy we iýmit merkezine hil ulgamynyň laýyklyk güwänamasy berildi','jemgyyetchilik-saglygy-we-iymit-merkezine-hil-ulgamynyn-layyklyk-guwanamasy-berildi','Jemgyýetçilik saglygy we iýmit merkezine hil ulgamynyň laýyklyk güwänamasy berildi Türkmenistanyň Saglygy goraýyş we derman senagaty ministrliginiň Döwlet arassaçylyk we keselleriň ýaýramagyna garşy göreşmek gullugynyň…','<h1 class=\"blog_header\" itemprop=\"name\" style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-weight: bolder; font-stretch: normal; font-size: 25px; font-family: Commissioner, Helvetica, sans-serif; bottom: 0px; color: rgb(0, 0, 0); padding: 0px;\">Jemgyýetçilik saglygy we iýmit merkezine hil ulgamynyň laýyklyk güwänamasy berildi</h1><div class=\"main_image media-object responsive\" style=\"margin-bottom: 5px; margin-top: 5px; color: rgb(68, 68, 68); font-family: &quot;PT Root UI&quot;, Helvetica, sans-serif; font-size: 15px;\"><span class=\"thumb\"><a href=\"https://turkmenportal.com/images/uploads/blogs/webp/b3d0534d24df38e3c3f3de3096dcbef5.webp\" class=\"fancybox\" rel=\"blog\" data-fancybox=\"blog\" data-width=\"1200\" data-height=\"811\" style=\"color: rgb(0, 114, 214); cursor: zoom-in;\"><source media=\"(min-width: 1200px)\" type=\"image/webp\" srcset=\"/images/uploads/cache/blogs/b3d0534d24df38e3c3f3de3096dcbef5-8981725-382x254-2.webp\" width=\"382\" height=\"258\"><source media=\"(min-width: 1200px)\" type=\"image/jpeg\" srcset=\"/images/uploads/cache/blogs/b3d0534d24df38e3c3f3de3096dcbef5-8981725-382x254-2.jpg\" width=\"382\" height=\"258\"><img src=\"https://turkmenportal.com/images/uploads/cache/blogs/b3d0534d24df38e3c3f3de3096dcbef5-8981725-382x254-2.jpg\" alt=\"Jemgyýetçilik saglygy we iýmit merkezine hil ulgamynyň laýyklyk güwänamasy berildi\" title=\"Jemgyýetçilik saglygy we iýmit merkezine hil ulgamynyň laýyklyk güwänamasy berildi\" itemprop=\"associatedMedia\" style=\"border: 0px; max-width: 100%; border-radius: 5px;\"></a></span></div><div class=\"article_text\" itemprop=\"articleBody\" style=\"font-family: &quot;PT Root UI&quot;, sans-serif; padding-bottom: 10px; font-size: 16px; line-height: 1.57; margin: 18px 0px; color: rgb(0, 0, 0);\"><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Türkmenistanyň Saglygy goraýyş we derman senagaty ministrliginiň Döwlet arassaçylyk we keselleriň ýaýramagyna garşy göreşmek gullugynyň Jemgyýetçilik saglygy we iýmit merkezine hil ulgamynyň laýyklyk güwänamasy&nbsp;<strong style=\"font-weight: bold;\"><a href=\"https://www.turkmenmetbugat.gov.tm/tk/newspapers/2/articles/156319\" target=\"_blank\" style=\"color: rgb(0, 114, 214);\">berildi</a></strong>. Munuň özi merkezde geçirilýän barlaghana-synag işleriniň «Hil menejmentiniň ulgamy» diýen ugur boýunça TDS ISO 9001 standartynyň bellenen talaplaryna laýyk gelýändigini tassyklaýar.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Ozal habar berşimiz ýaly, Arkadag şäheriniň bir ýyllygynyň bellenilen gününde «Arkadag Medisina Klasteri Menejment» kärhanasyna hem Türkmenistanyň sertifikatlaşdyryş ulgamy tarapyndan şeýle güwänama berilipdi.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Türkmen halkynyň Milli Lideriniň 2016-njy ýylyň iýulynda açylyp ulanmaga berlen Jemgyýetçilik saglygy we iýmit merkezi ilata hyzmatlary hödürleýän döwrebap merkezleriň biridir. Onda geçirilýän barlaghana-gözegçilik işleriniň kämilleşdirilmegi hem-de halkara standartlara laýyklykda amala aşyrylmagy ýurtda «Saglyk» Döwlet maksatnamasynyň üstünlikli durmuşa geçirilýändigini aýdyň görkezýär. Bu ýerdäki işlere ISO 9001 standartynyň ornaşdyrylmagy merkeziň hünärmenleriniň öz işlerini ýokary derejede ýola goýýandygyny, zerur hyzmatlaryň gyşarnyksyz berjaý edilýändigini tassyklaýar.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">ISO 9001 — bu dünýäde hili dolandyrmak boýunça ykrar edilen standart bolup, dürli görnüşli edaralara, guramalara işini kämilleşdirmäge, müşderileriň talaplaryny ödemäge hem-de özüniň hile ygrarlylygyny görkezmäge ýardam edýär. Onuň talaplary hil menejment ulgamyny döretmegiň, işe ornaşdyrmagyň, saklamagyň we yzygiderli ösdürmegiň tertibini kesgitleýär.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Halkara guramalar bilen özara hyzmatdaşlygyň çäklerindäki işleriň netijesinde 2019-njy ýylyň sentýabrynda Jemgyýetçilik saglygy we iýmit merkeziniň referens barlaghanaly wirusologiýa bölümine Bütindünýä Saglygy Goraýyş Guramasy tarapyndan dümew boýunça Milli merkez derejesi berildi hem-de ol bu derejäni 2024-nji ýylda-da saklamagyny dowam edýär.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Merkeziň bu bölüminde gyzamyk we gyzylja ýokanç kesellerini anyklamak boýunça BSGG tarapyndan iberilen gözegçilik nusgalyklarynyň barlaglary geçirilip, olaryň netijesi barlaghananyň hünärmenleriniň iş başarnygyna bildirilýän talaplaryň ýokary derejede saklanýandygyny görkezýär.</p></div>','habarlar/20240718/669919362ad45378.jpeg',NULL,'2024-07-18 09:00:00',1,0,115,'2024-07-18 09:00:00','2026-10-28 11:40:35'),(2,'tm','Türkmenistanyň saglygy goraýyş ulgamynyň wekilleri BSGG-niň Astanadaky okuwlaryna gatnaşýarlar','turkmenistanyn-saglygy-gorayysh-ulgamynyn-wekilleri-bsgg-nin-astanadaky-okuwlaryna-gatnashyarlar','Türkmenistanyň saglygy goraýyş ulgamynyň wekilleri BSGG-niň Astanadaky okuwlaryna gatnaşýarlar Türkmenistanyň saglygy goraýyş ulgamynyň hünärmenleri Bütindünýä Saglygy Goraýyş Guramasynyň Ýewropa bölüminiň Astana…','<h1 class=\"blog_header\" itemprop=\"name\" style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-weight: bolder; font-stretch: normal; font-size: 25px; font-family: Commissioner, Helvetica, sans-serif; bottom: 0px; color: rgb(0, 0, 0); padding: 0px;\">Türkmenistanyň saglygy goraýyş ulgamynyň wekilleri BSGG-niň Astanadaky okuwlaryna gatnaşýarlar</h1><div class=\"main_image media-object responsive\" style=\"margin-bottom: 5px; margin-top: 5px; color: rgb(68, 68, 68); font-family: &quot;PT Root UI&quot;, Helvetica, sans-serif; font-size: 15px;\"><span class=\"thumb\"><a href=\"https://turkmenportal.com/images/uploads/blogs/webp/133c22858429acf7921505ba955de20c.webp\" class=\"fancybox\" rel=\"blog\" data-fancybox=\"blog\" data-width=\"693\" data-height=\"461\" style=\"color: rgb(0, 114, 214); cursor: zoom-in;\"><source media=\"(min-width: 1200px)\" type=\"image/webp\" srcset=\"/images/uploads/cache/blogs/133c22858429acf7921505ba955de20c-8981408-382x254-2.webp\" width=\"382\" height=\"254\"><source media=\"(min-width: 1200px)\" type=\"image/jpeg\" srcset=\"/images/uploads/cache/blogs/133c22858429acf7921505ba955de20c-8981408-382x254-2.jpeg\" width=\"382\" height=\"254\"><img src=\"https://turkmenportal.com/images/uploads/cache/blogs/133c22858429acf7921505ba955de20c-8981408-382x254-2.jpeg\" alt=\"Türkmenistanyň saglygy goraýyş ulgamynyň wekilleri BSGG-niň Astanadaky okuwlaryna gatnaşýarlar\" title=\"Türkmenistanyň saglygy goraýyş ulgamynyň wekilleri BSGG-niň Astanadaky okuwlaryna gatnaşýarlar\" itemprop=\"associatedMedia\" style=\"border: 0px; max-width: 100%; border-radius: 5px;\"></a></span></div><div class=\"article_text\" itemprop=\"articleBody\" style=\"font-family: &quot;PT Root UI&quot;, sans-serif; padding-bottom: 10px; font-size: 16px; line-height: 1.57; margin: 18px 0px; color: rgb(0, 0, 0);\"><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Türkmenistanyň saglygy goraýyş ulgamynyň hünärmenleri Bütindünýä Saglygy Goraýyş Guramasynyň Ýewropa bölüminiň Astana şäherinde geçirilen saglygy goraýyş guramalarynda üstünlikli dolandyryş başarnyklary boýunça okuwlaryna gatnaşýarlar.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Okuwa Bütindünýä Saglygy Goraýyş Guramasynyň Ýewropa sebitiniň sekiz ýurdundan jemgyýetçilik saglygy goraýyş wekilleri gatnaşýar diýip, HHM Gazagystan Respublikasynyň Saglygy goraýyş ministrligine salgylanyp&nbsp;<a href=\"http://turkmenistaninfo.gov.tm/news/6523\" target=\"_blank\" style=\"color: rgb(0, 114, 214);\">habar berdi.</a></p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Saglygy goraýyş işgärleriniň ýolbaşçylyk ukybyny güýçlendirmeklige gönükdirilen okuw kursy BSGG-niň Ýewropa iş meýilnamasynyň 2020 — 2025-nji ýyllarynyň çäginde işlenip düzüldi.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Okuw meýilnamasy häzirki zaman şertlerinde jemgyýetiň saglygy bilen baglanyşykly ýüze çykýan kynçylyklara netijeli jogap bermäge mümkinçilik berýän dolandyryş we strategiki meýilleşdiriş endiklerini ösdürmäge gönükdirilen okuwlary we tejribe alyşmagy öz içine alýar.</p></div>','habarlar/20240718/6699198d22794594.jpeg',NULL,'2024-07-18 09:00:00',1,0,116,'2024-07-18 09:00:00','2026-10-28 11:40:35'),(3,'tm','Lebap welaýat köpugurly hassahanasyna \"Arkadag Medisina Klasteri Menejment\" kärhanasynda öndürilen önümler berildi','lebap-welayat-kopugurly-hassahanasyna-arkadag-medisina-klasteri-menejment-karhanasynda-ondurilen-onumler-berildi','Lebap welaýat köpugurly hassahanasyna \"Arkadag Medisina Klasteri Menejment\" kärhanasynda öndürilen önümler berildi Lebap welaýat köpugurly hassahanasyna \"Arkadag Medisina Klasteri Menejment\" kärhanasynda öndürilen…','<h1 class=\"blog_header\" itemprop=\"name\" style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-weight: bolder; font-stretch: normal; font-size: 25px; font-family: Commissioner, Helvetica, sans-serif; bottom: 0px; color: rgb(0, 0, 0); padding: 0px;\">Lebap welaýat köpugurly hassahanasyna \"Arkadag Medisina Klasteri Menejment\" kärhanasynda öndürilen önümler berildi</h1><div class=\"main_image media-object responsive\" style=\"margin-bottom: 5px; margin-top: 5px; color: rgb(68, 68, 68); font-family: &quot;PT Root UI&quot;, Helvetica, sans-serif; font-size: 15px;\"><span class=\"thumb\"><a href=\"https://turkmenportal.com/images/uploads/blogs/webp/c90fd8172582fa673c2dfbcc125f2704.webp\" class=\"fancybox\" rel=\"blog\" data-fancybox=\"blog\" data-width=\"1152\" data-height=\"769\" style=\"color: rgb(0, 114, 214); cursor: zoom-in;\"><source media=\"(min-width: 1200px)\" type=\"image/webp\" srcset=\"/images/uploads/cache/blogs/c90fd8172582fa673c2dfbcc125f2704-8980559-382x254-2.webp\" width=\"382\" height=\"255\"><source media=\"(min-width: 1200px)\" type=\"image/jpeg\" srcset=\"/images/uploads/cache/blogs/c90fd8172582fa673c2dfbcc125f2704-8980559-382x254-2.jpg\" width=\"382\" height=\"255\"><img src=\"https://turkmenportal.com/images/uploads/cache/blogs/c90fd8172582fa673c2dfbcc125f2704-8980559-382x254-2.jpg\" alt=\"Lebap welaýat köpugurly hassahanasyna \" arkadag=\"\" medisina=\"\" klasteri=\"\" menejment\"=\"\" kärhanasynda=\"\" öndürilen=\"\" önümler=\"\" berildi\"=\"\" title=\"Lebap welaýat köpugurly hassahanasyna \" itemprop=\"associatedMedia\" style=\"border: 0px; max-width: 100%; border-radius: 5px;\"></a></span></div><div class=\"article_text\" itemprop=\"articleBody\" style=\"font-family: &quot;PT Root UI&quot;, sans-serif; padding-bottom: 10px; font-size: 16px; line-height: 1.57; margin: 18px 0px; color: rgb(0, 0, 0);\"><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Lebap welaýat köpugurly hassahanasyna \"Arkadag Medisina Klasteri Menejment\" kärhanasynda öndürilen önümler gowşuryldy.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Lukmançylyk edarasyna hassalar üçin bir gezek ulanylýan agyz-burun örtükleri, lukmançylyk başgaplary, halatlar, aýakgap örtükleri berildi. Olar Gurbanguly Berdimuhamedow adyndaky Howandarlyga mätäç çagalara hemaýat bermek boýunça haýyr-sahawat gaznasy tarapyndan sowgat hökmünde iberildi.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Agzalan lukmançylyk önümlerini öndürmek üçin kärhananyň işe başlamagyndan kän wagt geçmänkä, Lebap welaýat köpugurly hassahanasy ilkinji bolup önümleriň bir tapgyryny aldy.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Ýeri gelende, ýakynda \"Arkadag Medisina Klasteri Menejment\" kärhanasyna Hil ulgamynyň laýyklyk sertifikatynyň berlendigini hem bellemek gerek.</p></div>','habarlar/20240718/66991bdd66c9e851.jpg',NULL,'2024-07-18 09:00:00',1,0,117,'2024-07-18 09:00:00','2026-10-28 11:40:35'),(4,'tm','Türkmenistanyň wekiliýeti Merkezi Aziýada saglygy goraýyşa maýa goýumlary boýunça halkara foruma gatnaşýar','turkmenistanyn-wekiliyeti-merkezi-aziyada-saglygy-gorayysha-maya-goyumlary-boyuncha-halkara-foruma-gatnashyar','Türkmenistanyň wekiliýeti Merkezi Aziýada saglygy goraýyşa maýa goýumlary boýunça halkara foruma gatnaşýar Türkmenistanyň Saglygy goraýyş we derman senagaty ministrliginiň wekiliýeti Bişkekde «Saglyk iň gowy maýa…','<h1 class=\"blog_header\" itemprop=\"name\" style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-weight: bolder; font-stretch: normal; font-size: 25px; font-family: Commissioner, Helvetica, sans-serif; bottom: 0px; color: rgb(0, 0, 0); padding: 0px;\">Türkmenistanyň wekiliýeti Merkezi Aziýada saglygy goraýyşa maýa goýumlary boýunça halkara foruma gatnaşýar</h1><div class=\"main_image media-object responsive\" style=\"margin-bottom: 5px; margin-top: 5px; color: rgb(68, 68, 68); font-family: &quot;PT Root UI&quot;, Helvetica, sans-serif; font-size: 15px;\"><span class=\"thumb\"><a href=\"https://turkmenportal.com/images/uploads/blogs/webp/520f790a28d2b77ca7e35327ebd38cff.webp\" class=\"fancybox\" rel=\"blog\" data-fancybox=\"blog\" data-width=\"582\" data-height=\"323\" style=\"color: rgb(0, 114, 214); cursor: zoom-in;\"><source media=\"(min-width: 1200px)\" type=\"image/webp\" srcset=\"/images/uploads/cache/blogs/520f790a28d2b77ca7e35327ebd38cff-8979973-382x254-2.webp\" width=\"382\" height=\"212\"><source media=\"(min-width: 1200px)\" type=\"image/png\" srcset=\"/images/uploads/cache/blogs/520f790a28d2b77ca7e35327ebd38cff-8979973-382x254-2.png\" width=\"382\" height=\"212\"><img src=\"https://turkmenportal.com/images/uploads/cache/blogs/520f790a28d2b77ca7e35327ebd38cff-8979973-382x254-2.png\" alt=\"Türkmenistanyň wekiliýeti Merkezi Aziýada saglygy goraýyşa maýa goýumlary boýunça halkara foruma gatnaşýar\" title=\"Türkmenistanyň wekiliýeti Merkezi Aziýada saglygy goraýyşa maýa goýumlary boýunça halkara foruma gatnaşýar\" itemprop=\"associatedMedia\" style=\"border: 0px; max-width: 100%; border-radius: 5px;\"></a></span></div><div class=\"article_text\" itemprop=\"articleBody\" style=\"font-family: &quot;PT Root UI&quot;, sans-serif; padding-bottom: 10px; font-size: 16px; line-height: 1.57; margin: 18px 0px; color: rgb(0, 0, 0);\"><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Türkmenistanyň Saglygy goraýyş we derman senagaty ministrliginiň wekiliýeti Bişkekde «Saglyk iň gowy maýa goýumdyr» şygary bilen geçirilýän Merkezi Aziýada saglygy goraýyşa maýa goýumlary boýunça ilkinji halkara foruma gatnaşýar.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Forum Bütindünýä Saglygy Goraýyş Guramasyna agza bolan Aziýa ýurtlarynyň bäşisinde-de durnukly ösüş üçin saglyk maýa goýumlarynyň özgeriş mümkinçiligini görkezmek boýunça halkara, sebit we milli gyzyklanýan taraplary bir ýere jemledi.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Forum Gyrgyz Respublikasynyň Prezidentiniň howandarlygynda geçirilýär we BSGG-niň Ýewropa boýunça sebit bölümi hem-de Gyrgyzystanyň Saglygy goraýyş ministrligi tarapyndan guralýar.</p><blockquote style=\"padding: 0px 0px 0px 20px; margin-bottom: 20px; margin-left: 25px; border-left: 4px solid rgba(167, 31, 31, 0.64); position: relative; border-top: none; border-right: none; border-bottom: none; border-image: initial;\"><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; font-weight: bolder; line-height: 30px; font-style: italic; word-break: break-word; text-align: justify;\">«Demografik we ykdysady görkeziji — Merkezi Aziýanyň ösüşini çaltlaşdyrmak, saglygy goraýyş ýaly möhüm pudaklara maýa goýmak millionlarça adamyň durmuşyny gowulandyrmak üçin ajaýyp mümkinçilik döredýär» diýip, Bütindünýä Saglygy Goraýyş Guramasynyň Ýewropa boýunça sebit direktory Hans Kluge öz çykyşynda belledi.</p></blockquote><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Merkezi Aziýada 76,5 million adam ýaşaýar, olaryň 30%-i 14 ýaş ýa-da ondan kiçi ýaşlylardyr. Soňky iki onýyllygyň dowamynda erkekleriň ömri ortaça 5,2 ýyl, aýallar üçin 4 ýyl ýokarlandy. Eneleriň ölümi iki esse azaldy.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Merkezi Aziýada saglygy we abadançylygy goldamak üçin «Ýol kartasy» kabul edileli bäri Gazagystan, Gyrgyzystan, Täjigistan, Türkmenistan we Özbegistan 11 ugur boýunça saglygy goraýyş pudagynda hyzmatdaşlygy artdyrýar.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; text-align: justify;\">Bütindünýä Saglygy Goraýyş Guramasynyň metbugat beýanatyna görä, forumyň ýene bir maksady saglyk infrastrukturasyna we innowasiýa maýa goýmak üçin täze hyzmatdaşlygy hem-de borçnamalary döretmekden ybaratdyr.</p></div>','habarlar/20240718/66991ca1f0074326.jpg',NULL,'2024-07-18 09:00:00',1,1,119,'2024-07-18 09:00:00','2026-10-28 18:20:28'),(5,'tm','Türkmenistanda saglygy goraýşyň täze edaralary açyldy.','turkmenistanda-saglygy-gorayshyn-taze-edaralary-achyldy','Saglygy goraýyş we derman senagaty işgärleriniň hünär baýramyny her ýylda giňden baýram etmek ýurdumyzda asylly däbe öwrüldi. Öňki ýyllarda bolşy ýaly, şu ýylda hem bu şanly sene mynasybetli birnäçe iri çäreler…','<span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Saglygy goraýyş we derman senagaty işgärleriniň hünär baýramyny her ýylda giňden baýram etmek ýurdumyzda asylly däbe öwrüldi. Öňki ýyllarda bolşy ýaly, şu ýylda hem bu şanly sene mynasybetli birnäçe iri çäreler geçirilýär. Şu gün paýtagtymyzda gurlup ulanmaga berlen 400 orunlyk Halkara sagaldyş-dikeldiş merkeziniň we 250 orunlyk Halkara fiziologiýa ylmy-kliniki merkeziniň açylyş dabaralary şol çäreleriň esasylarynyň biri boldy. Bu dabaralara türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gahryman Arkadagymyz Gurbanguly Berdimuhamedow gatnaşdy. Täze desgalaryň açylmagy hemişe döwrebaplaşdyrylyp durulýan milli saglygy goraýyş ulgamyna Türkmenistanda aýratyn üns berilýändiginiň aýdyň güwäsi boldy. Ilatyň saglygyny, bagtyýar durmuşyny we abadançylygyny goramak Gahryman Arkadagymyzyň başyny başlan we häzirki wagtda hormatly Prezidentimiz Serdar Berdimuhamedowyň baştutanlygynda üstünlikli amala aşyrylýan döwlet syýasatynyň ileri tutulýan ugrudyr. Köp ýyllaryň dowamynda ýurdumyzyň saglygy goraýyş ulgamyna ýolbaşçylyk eden türkmen halkynyň Milli Lideri Gurbanguly Berdimuhamedowyň başlangyjy bilen öňe sürlen we işlenip taýýarlanylan «Saglyk» Döwlet maksatnamasynyň yzygiderli durmuşa geçirilmegi netijesinde ýurdumyzda soňky ýyllarda bu ulgamyň düzümleri giňeldilip, maddy-enjamlaýyn binýady pugtalandyrylýar, innowasion tehnologiýalar we iň gowy dünýä tejribeleri we lukmançylyk ulgamyndaky gazananlary işjeň ornaşdyrylýar.&nbsp;</span><br>','habarlar/20241011/6708e517e1c49141.jfif',NULL,'2024-10-11 09:00:00',1,1,120,'2024-10-11 09:00:00','2026-10-28 18:20:27'),(6,'tm','Ýaşlaryň bagtyýarlygy - \"Watanymyzyň buýsanjy\" ady bilen döredijilik bäsleşigi geçirildi.','yashlaryn-bagtyyarlygy-watanymyzyn-buysanjy-ady-bilen-doredijilik-basleshigi-gechirildi','Türkmen halkynyň Milli Lideri Gahryman Arkadagymyzyň we Arkadagly Gahryman Serdarymyzyň talyp ýaşlar barada edýän bimöçber aladalaryndan we berýän gymmatly maslahatlaryndan ugur alyp, Berkarar döwletiň täze eýýamynyň…','<span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Türkmen halkynyň Milli Lideri Gahryman Arkadagymyzyň we Arkadagly Gahryman Serdarymyzyň talyp ýaşlar barada edýän bimöçber aladalaryndan we berýän gymmatly maslahatlaryndan ugur alyp, Berkarar döwletiň täze eýýamynyň Galkynyşy döwründe “Pähim – paýhas ummany Magtymguly Pyragy ýylynda” Mukaddes Garaşsyzlyk baýramçylygynyň şanly 33 ýyllygyna bagyşlanyp Arkadag, Aşgabat şäherleriniň we Ahal welaýatynyň orta hünär okuw mekdepleriniň talyp ýaşlarynyň arasynda “Garaşsyzlyk ak ýolunda Berkararlyk Penasynda – Arkadagymyz bar. Döwletlilik rowanynda – Arkadagly Serdarymyz bar” şygary bilen 2024 – nji ýylyň 17 – nji sentýabrynda Türkmenistanyň Bilim ministrliginiň, Türkmenistanyň Saglygy goraýyş we derman senagaty ministrliginiň, Türkmenistanyň Kärdeşler arkalaşygynyň Milli merkezini, Türkmenistanyň Magtymguly adyndaky Ýaşlar guramasynyň Merkezi Geňeşi we Indira Gandi adyndaky Aşgabat lukmançylyk orta okuw mekdebi bilen bilelikde “Ýaşlaryň bagtyýarlygy – Watanymyzyň buýsanjy” ady bilen döredijilik bäsleşigi geçirildi.&nbsp;</span><br><div><div style=\"color: rgb(119, 119, 119); font-family: \" open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\"><font size=\"4\" face=\"arial\" color=\"#000000\">Berkarar döwletiň täze eýýamynyň Galkynyşy döwründe “Pähim – paýhas ummany Magtymguly Pyragy” ýylynda Gahryman Arkadagymyzyň “Türkmeniň döwletlilik ýörelgesi” atly kitabynda “Iň gymmatly miras terbiýe, terbiýäniň özeni bolsa ylym-bilimdir” diýen altyn jümlelerinden ugur alyp, türkmen ýaşlaryny bagtyýarlyk döwrüniň ruhunda terbiýelemek, olarda watançylyk, ynsanperwerlik duýgularyny kämilleşdirmek we çeperçilik ukyp-başarnyklaryny ýüze çykarmak maksady bilen bäsleşik yglan edildi. Bäsleşigiň başynda şerti bilen tanyşdyryldy. Bäsleşigi adalatly bahalandyrjak emin agzalar bellenildi. Bäsleşigiň soňunda has tapawutly çykyş edenler Baş baýraga we 1, 2, 3-nji ýerlere mynasyp bolan dört sany ýeniji toparlar yglan edildi we olar Türkmenistanyň Bilim ministrliginiň, Türkmenistanyň Saglygy goraýyş we derman senagaty ministrliginiň, Türkmenistanyň Kärdeşler arkalaşygynyň Milli merkeziniň hormat hatlary we gymmat bahaly sowgatlary bilen sylaglandylar. Bäsleşige gatnaşyjylyr bäsleşigiň ahyrynda Gahryman Arkadagymyzyň we Arkadagly Gahryman Serdarymyzyň janlarynyň sag, ömürleriniň uzak, alyp barýan tutumly işleriniň elmydama rowaçlyklara beslenmegi arzuw etdiler.</font></div><div style=\"color: rgb(119, 119, 119); font-family: \" open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: \" open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"font-weight: 700 !important;\"><i>Baş baýragyň eýesi – I.Gandi adyndaky Aşgabat lukmançylyk orta okuw mekdebi</i></span></font></div><div style=\"color: rgb(119, 119, 119); font-family: \" open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"font-weight: 700 !important;\"><i><br></i></span></font></div><div style=\"color: rgb(119, 119, 119); font-family: \" open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"font-weight: 700 !important;\"><i>Birinji ýeriň eýesi -&nbsp; &nbsp;Aman Kekilow adyndaky Mugallymçylyk mekdebi</i></span></font></div><div style=\"color: rgb(119, 119, 119); font-family: \" open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"font-weight: 700 !important;\"><i>Ikinji ýeriň eýesi-D.Öwezow adyndaky Türkmen döwlet ýörite sazçylyk mekdebi&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</i></span></font></div><div style=\"color: rgb(119, 119, 119); font-family: \" open=\"\" sans\",=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 14px;=\"\" text-align:=\"\" justify;\"=\"\"><font size=\"4\" face=\"arial\" color=\"#000000\"><span style=\"font-weight: 700 !important;\"><i>Üçünji ýeriň eýesi&nbsp; &nbsp;-&nbsp; Aşgabat gurluşyk orta hünär okuw mekdebi</i></span></font></div></div>','habarlar/20241011/6708e6db37589990.jpg',NULL,'2024-09-23 09:00:00',1,1,121,'2024-09-23 09:00:00','2026-10-28 18:20:28'),(7,'tm','Arkadag şäherinde VI Wena baly açyldy.','arkadag-shaherinde-vi-wena-baly-achyldy','Şu gün Arkadag şäherinde VI Wena baly açyldy. Oňa türkmen halkynyň Milli Lideri, Halk Maslahatynyň Başlygy, Hormatly il ýaşulusy Gurbanguly Berdimuhamedow hormatly myhman hökmünde gatnaşdy. Bu barada TDH habar berýär.…','<p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; color: rgb(0, 0, 0); font-family: &quot;PT Root UI&quot;, sans-serif; font-size: 16px;\">Şu gün Arkadag şäherinde VI Wena baly açyldy. Oňa türkmen halkynyň Milli Lideri, Halk Maslahatynyň Başlygy, Hormatly il ýaşulusy Gurbanguly Berdimuhamedow hormatly myhman hökmünde gatnaşdy. Bu barada TDH habar berýär.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; color: rgb(0, 0, 0); font-family: &quot;PT Root UI&quot;, sans-serif; font-size: 16px;\">Bellenilişi ýaly, bu gezekki döredijilik çäresi ynsanperwer ulgamda iki ýurduň halklarynyň birek-biregiň medeni durmuşyna gyzyklanmalaryny, has ýakyn gatnaşyklary ýola goýmaga bolan tagallalaryny tassyklaýar. Şunuň bilen bir hatarda, bu çäräniň geçirilmegi Prezident Serdar Berdimuhamedowyň durmuşa geçirýän, dünýä jemgyýetçiliginiň ykrarnamasyna we goldawlaryna eýe bolan açyklyk, hoşniýetli goňşuçylyk we giň halkara hyzmatdaşlyk syýasatynyň netijesi bolup durýar.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; color: rgb(0, 0, 0); font-family: &quot;PT Root UI&quot;, sans-serif; font-size: 16px;\">Gahryman Arkadygyň ýardam-goldawlary bilen döredilen bilelikdäki «Galkynyş» simfoniki orkestri hem bu ulgamda alnyp barylýan netijeli ikitaraplaýyn hyzmatdaşlygyň nyşany bolup durýar. Türkmenistanda geçirilýän Wena balyny bilelikde guralýan ajaýyp çäreleriň biri hökmünde görkezmek bolar.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; color: rgb(0, 0, 0); font-family: &quot;PT Root UI&quot;, sans-serif; font-size: 16px;\">Iki ýüz ýyla golaý taryhy bolan Wena baly Awstriýanyň paýtagtynyň esasy nyşanlarynyň biri bolup, geçen döwürde özüniň meşhurlygyny ýitirmän, eýsem, Awstriýanyň, hatda Ýewropanyň çäklerinden hem daşary çykyp, dünýäniň köp sanly ýurtlarynda yzygiderli geçirilýän medeni çärä öwrüldi.</p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; word-break: break-word; color: rgb(0, 0, 0); font-family: &quot;PT Root UI&quot;, sans-serif; font-size: 16px;\">Bu döredijilik çäresiniň Arkadag şäherinde geçirilýändigi aýratyn ähmiýete eýedir diýip, çeşme belleýär.</p>','habarlar/20241011/6708e97128639292.jfif',NULL,'2024-10-11 09:00:00',1,1,122,'2024-10-11 09:00:00','2026-10-28 18:20:26'),(8,'tm','Las-Wegasda Microsoft Excel boýunça Dünýä çempionaty tamamlandy','las-wegasda-microsoft-excel-boyuncha-dunya-chempionaty-tamamlandy','Las-Wegasda Microsoft Excel boýunça Dünýä çempionaty tamamlandy. Bu ýaryş elektron tablisalary bilen işlemegiň höwesjeňleri we ussatlary üçin hakyky şüweleňe öwrüldi. Çäre kiber sport ýaryşlary üçin adaty bolan…','<div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Las-Wegasda Microsoft Excel boýunça Dünýä çempionaty tamamlandy. Bu ýaryş elektron tablisalary bilen işlemegiň höwesjeňleri we ussatlary üçin hakyky şüweleňe öwrüldi.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Çäre kiber sport ýaryşlary üçin adaty bolan meýdançada geçirilip, bütin dünýäden gatnaşyjylary ýygnady. Olar çylşyrymly ýumuşlary çözmekde ýaryşyp, Excel programmasyny ulanmakda öz ukyp-başarnyklaryny we döredijiliklerini görkezdiler. Ýaryşyň jemleýji tapgyry has dartgynly ýagdaýda geçirildi: gatnaşyjylar onlaýn-oýun meňzetmesinde 20 sany awatarlaryň görkezijilerine gözegçilik etmek üçin çylşyrymly formulalary işläp taýýarlamalydy. Bu hem diňe bir Excel programmany bilmekligi däl, eýsem üýtgeýän şertlere tiz uýgunlaşmak ukybyny hem talap etdi.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Netijede, Beýik Britaniýadan gelen maliýe geňeşçisi, 30 ýaşly Maýkl Jarman ýeňiji bolup, pul baýragyna hem-de “Excel ussaty” diýen ada mynasyp boldy. Çempionatyň guramaçysy Endrýu Grigolýunowiç, bu ýaryşyň geljekde iri baýrakly meşhur kiber sport görnüşi bolup, has köp gatnaşyjylary we tomaşaçylary özüne çekjekdigine ynam bildirdi.</font></div>','habarlar/20250205/67a34b853b250977.jpg',NULL,'2025-02-05 09:00:00',1,1,123,'2025-02-05 09:00:00','2026-10-28 18:20:26'),(9,'tm','«Galkynyş» milli at üstündäki oýunlar toparynyň gazanan halkara üstünligi dabaralanýar','galkynysh-milli-at-ustundaki-oyunlar-toparynyn-gazanan-halkara-ustunligi-dabaralanyar','1-nji fewralda Arkadag şäherinde Türkmenistanyň Prezidentiniň Ahalteke atçylyk toplumynyň «Galkynyş» milli at üstündäki oýunlar toparynyň Monako Knýazlygynyň Monte-Karlo şäherinde geçirilen 47-nji halkara sirk sungaty…','<span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">1-nji fewralda Arkadag şäherinde Türkmenistanyň Prezidentiniň Ahalteke atçylyk toplumynyň «Galkynyş» milli at üstündäki oýunlar toparynyň Monako Knýazlygynyň Monte-Karlo şäherinde geçirilen 47-nji halkara sirk sungaty festiwalynda ýeňiji bolmagy mynasybetli dabaraly çäreler geçirildi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Mälim bolşy ýaly, türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gahryman Arkadagymyzyň Monako Knýazlygynda saparda bolan günlerinde «Galkynyş» milli at üstündäki oýunlar topary Monte-Karloda geçirilen halkara sirk sungaty festiwalynda üstünlikli çykyş edip, Altyn baýraga we beýleki ýörite baýraklara mynasyp boldy. Munuň özi Milli Liderimiziň başlangyjy, hormatly Prezidentimiziň tagallalary bilen ýurdumyzyň sirk sungatynyň dünýä derejesine çykarylýandygynyň aýdyň güwäsine öwrüldi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Türkmen sirk sungatynyň ösüşinde «Galkynyş» milli at üstündäki oýunlar toparyna uly orun degişlidir. Bu topar 2007-nji ýylda türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gurbanguly Berdimuhamedowyň tagallasy esasynda döredildi. Toparyň dünýäniň dürli ýurtlarynda çykyş edip, sirk sungaty boýunça birnäçe abraýly halkara baýraklara, şol sanda 2013-nji ýylda Russiýa Federasiýasynyň Moskwa şäherinde geçirilen «IDOL» bütindünýä sirk sungaty festiwalynda, 2014-nji ýylda Italiýanyň Latina şäherinde geçirilen XVI halkara sirk festiwalynda, 2015-nji ýylda Hytaý Halk Respublikasynda guralan II halkara sirk sungaty festiwalynda, 2016-njy ýylda Gyrgyz Respublikasynyň Çolpon-Ata şäherinde geçirilen Çarwadarlaryň II bütindünýä oýunlarynda baş baýraklara, 2018-nji ýylda Russiýa Federasiýasynyň Sankt-Peterburg şäherinde bolan Fontankadaky I halkara sirk sungaty festiwalynda «Altyn Gaetano» altyn heýkeljigine mynasyp bolandygyny bellemek gerek.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">...Dabara Arkadag şäheriniň «Akhan» binasynyň öňündäki meýdançada badalga aldy. Bu ýerde ýurdumyzyň medeniýet we sungat işgärleriniň aýdym-sazly çykyşlary ýaýbaňlandyryldy. «Galkynyş» milli at üstündäki oýunlar toparynyň agzalary Akhan we Aba Annaýew şaýollarynyň ugry bilen Arkadag şäheriniň Görogly adyndaky döwlet atçylyk sirkine tarap ugradylar. Ýörişiň öňüni ellerinde Türkmenistanyň Döwlet baýdagy we Birleşen Milletler Guramasynyň baýdagy bolan atlylar çekdi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Gahryman Arkadagymyzyň yhlasy, hormatly Prezidentimiziň tagallalary bilen Köpetdagyň ajaýyp künjeginde bina edilen, sebitde ilkinji «akylly» şäher — Arkadag şäheri Türkmenistanyň durmuş-ykdysady ösüşiniň aýdyň nyşanyna öwrüldi. Arkadag şäheriniň durnukly ösüş, ekologik taýdan arassalygy, innowasion çözgütleri üçin halkara güwänamalardyr baýraklaryň birnäçesine mynasyp bolmagy hem bu iri şähergurluşyk taslamasynyň ýokary derejede durmuşa geçirilendigine şaýatlyk edýär. Täze şäherde milli binagärligiň iň gowy däpleri şähergurluşyk hem-de dizaýn boýunça häzirki zaman ýörelgeleri sazlaşykly utgaşýar. Onuň bezeg işlerinde behişdi ahalteke bedewleriniň şekiliniň ulanylmagyna möhüm ähmiýet berilýär. Bu ýerde Akhan atly bedewiň heýkeliniň ýerleşdirilmegi Arkadag şäheriniň şu günki we geljekki bedew batly ösüşlerini alamatlandyrýar.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Türkmenistanyň ussat halypa seýsi Gahryman Arkadagymyzyň hut özüniň seýislän Akhan bedewiniň üstünligi ahalteke atlarynyň şöhratyny has-da artdyrdy. Mälim bolşy ýaly, Türkmenistanyň Prezidentiniň Ahalteke atçylyk toplumyna degişli bu bedewiň iki aýagynyň üstünde çarpaýa galyp, 10 metr aralygy 4,19 sekuntda geçmegi Ginnesiň rekordlar kitabyna girizildi. Munuň özi şondan ozalky iň gowy netijeden iki esse ýokarydyr. Akhanyň bu üstünligi türkmen halkynyň Milli Lideriniň ägirt uly yhlasynyň, seýisçilik tejribesiniň ajaýyp netijesidir. Gahryman Arkadagymyzyň 2009-njy ýylda Akhany «Galkynyş» milli at üstündäki oýunlar toparyna sowgat bermegi toparyň täze üstünliklerine ýol açdy. Akhan bu topar bilen ençeme ýurtlarda çykyş edip, halkara festiwallaryň baş baýraklaryny gazanmaga mynasyp goşant goşdy.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Häzirki wagtda halkymyzyň baý medeni mirasyny, şol sanda behişdi bedewleri köpeltmek, ösdürip ýetişdirmek we seýislemek baradaky köpasyrlyk däplerini aýawly saklamak, öwrenmek, wagyz etmek boýunça giň gerimli işler amala aşyrylýar. Ýelden ýüwrük ahalteke bedewleri milli we dünýä medeniýetiniň gymmatlygy bolmak bilen, häzirki wagtda Garaşsyz, hemişelik Bitarap Watanymyzyň ýeten belent sepgitleriniň aýdyň beýanyna öwrüldi. Gözelligi, ýyndamlygy bilen göreni haýrana goýýan bedewleri seýislemek tutanýerli zähmeti, bilimi, söýgini, zehini talap edýär. Merdana pederlerimiz bu ugurda hyjuwly zähmet çekipdirler. Bedewleriň ajaýyp ahalteke tohumynyň kemala getirilmegi munuň aýdyň mysalydyr.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Ýurdumyzda ahalteke atlarynyň şan-şöhratyny artdyrmakda, milli seýisçilik sungatyny has-da kämilleşdirmekde, olary ösdürip ýetişdirmekde uly işleri bitiren halk seçgiçileriniň, ussat seýisleriň atlary ebedileşdirilýär. Şeýle şahsyýetleriň biri hem Aba Annaýewdir. Onuň atşynaslyk sungatyny ösdürmekde we bu sungatyň gadymy däplerini nesilden-nesle geçirmekde bitiren hyzmatlary örän uludyr. Aba Annaýew öz işiniň hakyky ussady bolup, saýlama bedewleriň köp sanlysyny ösdürip ýetişdirdi we seýisledi. Halypa seýsiň adynyň Arkadag şäheriniň esasy şaýollarynyň birine, şeýle hem «akylly» şäherdäki Halkara atçylyk akademiýasyna dakylmagy ýurdumyzda zehinli seýislere, halypalara goýulýan çuňňur hormatdan nyşandyr.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">...Ýol ugrunda Arkadag şäheriniň ýaşaýjylary, edara-kärhanalaryň işgärleri, talyplar toparyň agzalaryny mübäreklediler. Şeýle hem dabara gatnaşyjylaryň baýramçylyk ruhuny belende göterýän aýdym-sazly çykyşlar ýaýbaňlandyryldy. «Galkynyş» milli at üstündäki oýunlar toparynyň agzalaryny Görogly adyndaky döwlet atçylyk sirkiniň öňündäki meýdançada il sylagly ýaşulular, halypa atşynaslar garşy aldylar hem-de gazanan uly üstünlikleri bilen gutladylar.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Göroglynyň adyny göterýän döwlet atçylyk sirki hem şäheriň binagärlik keşbine özboluşly bezeg berýär. Onuň nal şekilinde gurlan binasy dünýä standartlaryna laýyk gelýän ýörite enjamlardyr tehnologiýalar bilen üpjün edildi. 1 müň 500 tomaşaça niýetlenen atçylyk sirki gysga wagtyň içinde şäheriň ýaşaýjylarynyň we myhmanlarynyň iň gelim-gidimli ýerleriniň birine öwrüldi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Dabaranyň hormatyna bu ýerde medeniýet, sungat işgärleriniň aýdym-sazly çykyşlary ýaýbaňlandyryldy. Türkmen halkynyň Milli Lideriniň howandarlygynda neşir edilýän “Arkadag” gazetiniň «Galkynyş» milli at üstündäki oýunlar toparynyň taryhy üstünligine bagyşlanan nobatdaky sany gazetiň okyjylary üçin özboluşly sowgat boldy. Dabara Türkmenistanyň Mejlisiniň Başlygy, Hökümet agzalary, harby we hukuk goraýjy edaralaryň ýolbaşçylary, Türkmenistanyň Halk Maslahatynyň Diwanynyň iş dolandyryjysy, welaýatlaryň, Aşgabat, Arkadag şäherleriniň häkimleri, Türkmenistanyň Prezidentiniň ýanyndaky Arkadag şäheriniň gurluşygy boýunça döwlet komitetiniň başlygy, ministrlikleriň we pudaklaýyn dolandyryş edaralarynyň, jemgyýetçilik guramalarynyň, Türkmenistandaky diplomatik wekilhanalaryň ýolbaşçylarydyr wekilleri, Koreýa Respublikasynyň işewürleri gatnaşdylar.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Çäräniň başynda «Galkynyş» milli at üstündäki oýunlar toparynyň agzalary sahna çagyryldy. Ýurdumyzyň bu meşhur topary Monakonyň Monte-Karlo şäherinde geçirilen halkara sirk sungaty festiwalynda Baş baýraga, ýaş ýetginjek eminleriň, Italiýanyň sirkiniň, festiwalyň tomaşaçylarynyň, Hindistanyň sirkiniň baýraklaryna hem-de Monte-Karlo 47-nji halkara sirk sungaty festiwalynyň şahadatnamasyna mynasyp boldy. Soňra dabara gatnaşyjylara türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gahryman Arkadagymyzyň Fransiýa Respublikasynyň Nissa şäheriniň Halkara howa menzilinde «Galkynyş» milli at üstündäki oýunlar toparynyň agzalary bilen duşuşygyndaky Gutlagy ýetirildi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Milli Liderimiz toparyň agzalaryna ýüzlenip, Türkmenistanyň dünýä ýurtlary, şol sanda Monako Knýazlygy bilen medeni hyzmatdaşlygy giň gerim bilen ösdürýändigini, milli atçylyk sportuny ilerletmek ugrunda giň möçberli işleriň alnyp barylýandygyny belledi. Şeýle hem Gahryman Arkadagymyz «Galkynyş» milli at üstündäki oýunlar toparynyň Monte-Karlo şäherinde geçirilen halkara sirk sungaty festiwalyna gatnaşmagynyň türkmen halkyny diýseň buýsandyrandygyny, behişdi bedewlerimiziň ençeme asyrlaryň dowamynda halkymyzyň ýakyn syrdaşy bolmak bilen, ýurdumyzyň ösüşleriniň beýanyna öwrülendigini aýtdy. Nygtalyşy ýaly, ata-babalarymyzyň «At — myrat», «Atym bar — ganatym bar» diýen parasatly sözleri halkymyzyň behişdi bedewlerine goýýan hormatyndan nyşandyr. Häzirki wagtda Arkadagly Gahryman Serdarymyzyň baştutanlygynda ahalteke bedewlerimiziň dünýädäki şan-şöhratyny has-da belende götermek, baş sanyny artdyrmak ugrunda giň möçberli işler alnyp barylýar.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Mälim bolşy ýaly, «Galkynyş» milli at üstündäki oýunlar topary 2007-nji ýylda döredildi. Toparyň işi bu günki günde has-da kämilleşdi. «Galkynyş» toparynyň agzalary ahalteke bedewlerinde çylşyrymly hereketleri ýerine ýetirýärler. At üstünde täsin oýunlary görkezýärler. Gahryman Arkadagymyz bu toparyň ençeme halkara ýaryşlarda üstünlikli çykyş edip, baş baýraklara mynasyp bolandygyny, dünýäniň çar künjünde türkmen tuguny belende göterendigini, dürli ýurtlarda geçirilen halkara sirk festiwallarynda 5 gezek baş baýraga mynasyp bolup, dünýä çempiony diýen belent derejä eýe bolandygyny kanagatlanma bilen belledi. “Ynha, bu gün hem Monte-Karlo şäherinde geçirilen sirk sungatynyň halkara festiwalynda türkmen tuguny belentde parladyp, Baş baýraga mynasyp bolduňyz. Ahalteke bedewlerimiziň şan-şöhratyny dünýä ýaýdyňyz. Siziň geljekde hem halkara bäsleşiklerde üstünlikli çykyş edip, milli atçylyk sungatymyzyň şan-şöhratyny beýgeltjekdigiňize berk ynanýaryn” diýip, türkmen halkynyň Milli Lideri aýtdy. Türkmenistanyň Halk Maslahatynyň Başlygy «Galkynyş» toparynyň agzalaryny täze ýylyň — Halkara parahatçylyk we ynanyşmak ýylynyň ilkinji aýynda gazanan uly üstünligi — beýik ýeňşi bilen tüýs ýürekden gutlap, olara berk jan saglyk, maşgala abadançylygyny, alyp barýan işlerinde mundan beýläk-de uly üstünlikleri arzuw etdi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Dabara gatnaşyjylar Gahryman Arkadagymyzyň Gutlagyny uly ruhubelentlik bilen diňlediler. Soňra hormatly Prezidentimiz Serdar Berdimuhamedow sanly ulgam arkaly «Galkynyş» milli at üstündäki oýunlar toparyna Gutlag bilen ýüzlendi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Döwlet Baştutanymyz toparyň agzalaryny Halkara parahatçylyk we ynanyşmak ýylynyň ilkinji aýynda Monako Knýazlygynyň Monte-Karlo şäherinde geçirilen halkara sirk sungaty festiwalynda gazanan uly üstünligi, ýagny Baş baýraga hem-de ýörite baýraklara mynasyp bolmagy bilen tüýs ýürekden gutlady. “Garaşsyz, hemişelik Bitarap döwletimizde sirk sungaty yzygiderli ösdürilýär. Türkmen halkynyň Milli Lideri Gahryman Arkadagymyzyň başlangyjy bilen ýurdumyzda sirk sungaty has-da kämilleşdirildi. Häzirki döwürde milli sirk sungatynyň gerimini giňeltmek hem-de halkara hyzmatdaşlygy ösdürmek ugrunda giň möçberli işler alnyp barylýar” diýip hormatly Prezidentimiz belledi hem-de bu ugurdaky işleriň geljekde hem dowam etdiriljekdigini aýtdy. Nygtalyşy ýaly, Arkadag şäheriniň Görogly adyndaky döwlet atçylyk sirkinde at üstünde oýnalýan milli oýunlary kämilleşdirmek üçin ähli şertler döredildi. Munuň özi ýurdumyzda sirk sungatynyň has-da ösdürilýändiginiň aýdyň güwäsidir. Gahryman Arkadagymyzyň başlangyjy bilen döredilen «Galkynyş» milli at üstündäki oýunlar topary yzygiderli ýeňiş gazanyp, Watanymyzyň abraýyna abraý goşýar.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">«Galkynyş» toparynyň türgenleri diňe bir ýurdumyzda däl, eýsem, dünýäniň ençeme döwletlerinde geçirilýän halkara bäsleşiklerde baş baýraklara mynasyp bolup, türkmen tuguny belende galdyrdylar. Sirk dünýäsiniň iň meşhur bäsleşigi hasaplanýan Monte-Karlo sirk sungaty festiwalynda hem bu topar täsin çykyşlary bilen tomaşaçylary we emin agzalaryny haýran galdyrdy. Şunuň bilen baglylykda, hormatly Prezidentimiz festiwalda «Galkynyş» milli at üstündäki oýunlar toparynyň Baş baýraga hem-de ýörite baýraklara mynasyp bolmagynyň ýurdumyzyň halkara abraýyny belende göteren şatlykly waka bolandygyny belläp, toparyň agzalaryny bu uly üstünlik bilen ýene-de bir gezek tüýs ýürekden gutlady hem-de berk jan saglyk, alyp barýan işlerinde uly üstünlikleri arzuw etdi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Hormatly Prezidentimiz Serdar Berdimuhamedowyň Gutlagy şowhunly el çarpyşmalar bilen garşylanyldy.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Dabaranyň dowamynda «Galkynyş» milli at üstündäki oýunlar toparyna türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gurbanguly Berdimuhamedowyň adyndan 17 müň ýewro möçberinde pul sowgady gowşuryldy. Soňra hormatly Prezidentimiz Serdar Berdimuhamedowyň adyndan topara 3 million manat möçberinde pul sowgady gowşuryldy.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Toparyň agzalary halkara derejede geçirilýän şeýle iri ýaryşlara gatnaşyp, türkmen milli sirk sungatyny dünýä ýaýmaga, döredijilikli işlemäge döredilýän şertler hem-de zähmetine berlen ýokary baha üçin Gahryman Arkadagymyza, hormatly Prezidentimize tüýs ýürekden hoşallyklaryny beýan edip, özleri hakynda edilýän aladalaryň olary has-da netijeli zähmet çekmäge, ajaýyp ahalteke bedewlerimiziň şöhratyny mundan beýläk-de dünýä ýaýmak işine mynasyp goşant goşmaga ruhlandyrýandygyny bellediler.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Dabaranyň dowamynda hormatly Prezidentimiz Serdar Berdimuhamedowyň «Galkynyş» milli at üstündäki oýunlar toparynyň seýsi — topar ýolbaşçysy S.Pygyýewe “Türkmenistanyň at gazanan atşynasy” diýen hormatly ady dakmak hakyndaky Permany okaldy. Şeýle-de “Galkynyş” milli at üstündäki oýunlar toparyna Türkmenistanyň Magtymguly adyndaky Ýaşlar guramasynyň Merkezi geňeşi tarapyndan “Awaza” milli syýahatçylyk zolagyndaky “Daýanç” sagaldyş merkezine 10 günlük dynç alyş ýollanmasy, sport egin-eşikler toplumy, döwrebap tehnologiýalary özünde jemleýän enjamlar toplumy, ajaýyp türkmen halysy sowgat hökmünde gowşuryldy.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Soňra sirkiň sahnasynda şu günki dabara mynasybetli «Galkynyş» milli at üstündäki oýunlar toparynyň, medeniýet we sungat ussatlarynyň çykyşlary ýaýbaňlandyryldy, sirk tomaşasy görkezildi.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">«Galkynyşyň» oglan-gyzlarynyň bedewlere ussatlyk bilen erk edip, at üstünde ýerine ýetirýän dürli tilsimleri milli sirk sungatymyzyň özboluşly aýratynlygydyr. Toparyň çykyşy ilkinji pursatlardan tomaşaçylaryň ünsüni çekdi. Olaryň çykyşlarynyň hemişe uly gyzyklanma döredýändigini bellemek gerek. Olarda çeýelik, gözellik hem-de ussatlyk bir bitewi sazlaşygy emele getirip, tomaşanyň täsirliligini artdyrýar. Bu bolsa toparyň agzalarynyň öz işinde ussatlyk derejesine ýetendigini aýdyňlygy bilen görkezýär. Toparyň bu gezekki täsin çykyşlary hem şowhunly el çarpyşmalar bilen garşylanyldy.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">«Galkynyş» milli at üstündäki oýunlar topary milli sungatymyzy dünýäde giňden tanatmaga uly goşant goşmak bilen bir hatarda, ýurdumyzda ýaýbaňlandyrylýan dabaralarda, şanly seneler mynasybetli guralýan medeni-köpçülikleýin çärelerde çykyş edip, olaryň derejesini belende göterýär. Ajaýyp bedewleriň gözelligi, çeýeligi, çapyp barýan atyň üstünde dürli çylşyrymly hereketleri ýerine ýetirýän artistleriň ussatlygy tomaşaçylarda ýatdan çykmajak täsirleri galdyrýar.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Şeýlelikde, «Galkynyş» milli at üstündäki oýunlar toparynyň gazanýan halkara ýeňişleri türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gahryman Arkadagymyzyň atçylyk sportuny ösdürmek babatda başlangyçlarynyň häzirki wagtda hormatly Prezidentimiz Serdar Berdimuhamedowyň tagallalary bilen üstünlikli durmuşa geçirilýändiginiň aýdyň beýanydyr.</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">***</span><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><br style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\"><span style=\"color: rgb(0, 0, 0); font-family: arial; font-size: large; text-align: justify;\">Şol gün «Galkynyş» milli at üstündäki oýunlar toparynyň halkara baýraklara eýe bolmagy mynasybetli Arkadag şäheriniň «Märkaw» myhmanhanasynda aýdym-sazly dabara hem-de Aba Annaýew adyndaky Halkara atçylyk akademiýasynda ýurdumyzyň atşynaslarynyň, medeniýet, sungat, döredijilik işgärleriniň, talyplaryň gatnaşmagynda hoşallyk maslahaty geçirildi. Maslahatyň ahyrynda oňa gatnaşyjylar hormatly Prezidentimiz Serdar Berdimuhamedowyň adyna Ýüzlenme kabul etdiler.</span>','habarlar/20250205/67a34be0e2e30355.jpg',NULL,'2025-02-05 09:00:00',1,1,124,'2025-02-05 09:00:00','2026-10-28 18:20:26'),(10,'tm','Daşkentde türkmen halkynyň Milli Lideriniň “Hakyda göwheri” atly kitabynyň tanyşdyrylyş dabarasy geçirildi','dashkentde-turkmen-halkynyn-milli-liderinin-hakyda-gowheri-atly-kitabynyn-tanyshdyrylysh-dabarasy-gechirildi','2025-nji ýylyň 24-nji ýanwarynda Özbegistan Respublikasynyň Prezidentiniň ýanyndaky Döwlet dolandyryş akademiýasynda türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gurbanguly Berdimuhamedowyň…','<div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">2025-nji ýylyň 24-nji ýanwarynda Özbegistan Respublikasynyň Prezidentiniň ýanyndaky Döwlet dolandyryş akademiýasynda türkmen halkynyň Milli Lideri, Türkmenistanyň Halk Maslahatynyň Başlygy Gurbanguly Berdimuhamedowyň ýazan “Hakyda göwheri” atly kitabynyň tanyşdyrylyş dabarasy geçirildi.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Bu waka Özbegistan bilen Türkmenistanyň arasyndaky medeni we bilim gatnaşyklarynyň pugtalandyrylmagynda möhüm ädim boldy. Ýaňy-ýakynda kitap özbek diline terjime edilip neşir edildi, bu hem ony Özbegistanda has giň köpçülik üçin elýeterli edýär.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Çärä hökümet wekilleri, akademik toparlarynyň we jemgyýetçilik wekilleri gatnaşyp, kitabyň paýhas we ylham çeşmesi hökmündäki ähmiýeti barada belläp geçdiler. Gurbanguly Berdimuhamedow öz işinde milli barlygyň, ruhy mirasyň we jemgyýetiň ösüşiniň möhüm ugurlaryna ähmiýet berýär, bu bolsa Özbegistandaky okyjylar üçin ony döwrebäp eser edýär.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Gurbanguly Berdimuhamedow Özbegistanyň Ylymlar akademiýasynyň hormatly akademigidir.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Özbegistandaky Türkmenistanyň Adatdan daşary we Doly ygtyýarly ilçisi Şadurdy Meredow öz çykyşynda Özbegistanyň we Türkmenistanyň medeni-ynsanperwer gatnaşyklarynda şeýle medeni-wagyz çäreleriň uly ähmiýeti barada belledi.</font></div>','habarlar/20250205/67a34c3ae13de121.jpg',NULL,'2025-01-29 09:00:00',1,1,125,'2025-01-29 09:00:00','2026-10-28 18:20:26'),(11,'tm','Lomonosow döwlet uniwersitetiniň döredilenine 270 ýyl','lomonosow-dowlet-uniwersitetinin-doredilenine-270-yyl','1755-nji ýylyň 25-nji ýanwarynda şa zenany Ýelizaweta Petrowna Russiýanyň ilkinji uniwersitetini döretmek hakynda permana gol çekdi. Şu gün resmi taýdan MDU-nyň esaslandyrylan güni hasap edilýär. Uniwersitetiň Moskwada…','<div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">1755-nji ýylyň 25-nji ýanwarynda şa zenany Ýelizaweta Petrowna Russiýanyň ilkinji uniwersitetini döretmek hakynda permana gol çekdi. Şu gün resmi taýdan MDU-nyň esaslandyrylan güni hasap edilýär. Uniwersitetiň Moskwada döredilmegi köplenç iki adamyň – alym-ensiklopedist Mihail Wasilýewiç Lomonosowyň we onuň ýarany, Uniwersitetiň ilkinji kuratory, graf Iwan Iwanowiç Şuwalowyň tagallalarynyň netijesi boldy.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Başda okuw filosofiýa, lukmançylyk we hukuk fakultetlerinde alnyp barylýardy. Häzirki wagtda MDU-da birnäçe şahamça, takmynan 40 fakultet we 50 müňden gowrak talyp we aspirant bar. Bu ýerde 6 müňden gowrak professor we mugallym, 6 müň ylymlaryň kandidaty, 3 müň ylymlaryň doktory we 300-den gowrak Russiýanyň Ylymlar akademiýasynyň akademigi işleýär! MDU uly ylmy-barlag merkezine öwrüldi. Uniwersitet ylym, bilim we medeniýeti ösdürmekde ägirt uly rol oýnapdyr.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">1940-njy ýyldan bäri Moskwa döwlet uniwersiteti Mihail Wasilýewiç Lomonosowyň adyny göterýär. Mihail Wasilýewiç Lomonosow diňe bir ylymlary we bilimleri ýaýratmak arkaly Russiýanyň gülläp ösüp biljekdigine ynanýardy. Onuň ömrüniň esasy işi Russiýanyň ylmyny Ýewropa derejesine çykarmak bolup, bu işde ol ajaýyp üstünlik gazandy. Häzirki wagtda M.W. Lomonosow adyndaky MDU Russiýanyň iň gowy uniwersiteti we dünýäniň öňdebaryjy uniwersitetleriniň biridir.</font></div>','habarlar/20250205/67a34c9e26d32876.jpg',NULL,'2025-01-30 09:00:00',1,1,126,'2025-01-30 09:00:00','2026-10-28 18:20:26'),(12,'tm','Türkmenistan YHG-nyň Ýokary derejeli komitetiniň 1-nji mejlisiniň işine gatnaşdy','turkmenistan-yhg-nyn-yokary-derejeli-komitetinin-1-nji-mejlisinin-ishine-gatnashdy','Türkmenistanyň Daşary işler ministriniň orunbasary Ahmet Gurbanow 3-nji fewralda Tähranda geçirilen Ykdysady hyzmatdaşlyk guramasynyň Daşary işler ministrleriniň orunbasarlarynyň Ýokary derejeli komitetiniň 1-nji…','<div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Türkmenistanyň Daşary işler ministriniň orunbasary Ahmet Gurbanow 3-nji fewralda Tähranda geçirilen Ykdysady hyzmatdaşlyk guramasynyň Daşary işler ministrleriniň orunbasarlarynyň Ýokary derejeli komitetiniň 1-nji mejlisiniň işine gatnaşdy.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Şeýle hem mejlise sebit guramalarynyň, ýöriteleşdirilen düzüm birlikleriň, sebit institutlarynyň we YHG-nyň bölümleriniň ýolbaşçylary gatnaşdy.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Gün tertibine YHG-nyň çäginde maliýe we býudjet hyzmatdaşlygyny ösdürmek, “YHG göz ýetiriş 2025” (“ECO Vision 2025”) maksatlarynyň ýerine ýetirilişine garamak we bu köptaraplaýyn gurluşyň işleýiş mehanizmlerini kämilleşdirmek meseleleri girizildi.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Ahmet Gurbanow hyzmatdaşlygyň ileri tutulýan ugurlary boýunça Türkmenistanyň garaýyşlaryny we YHG-nyň ösüş strategiýasy baradaky tekliplerini beýan etdi. Türkmenistanyň Durnukly ulag baglanyşygynyň Ählumumy Atlasyny, Ählumumy energetika howpsuzlygy we durnuklylygy boýunça hyzmatdaşlygyň Bileleşigini döretmek we ýapyk aýlanyşykly ykdysadyýete geçmekde durnukly ösüş baradaky tekliplerine ünsi çekdi.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Şonuň bilen birlikde, sebitleýin integrasiýa, syýahatçylygy ösdürmek, adam maýasyny we institusional mümkinçilikleri güýçlendirmek üçin gural hökmünde YHG-nyň Söwda ylalaşygynyň netijeli durmuşa geçirilmeginiň ähmiýeti bellendi.</font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\"><br></font></div><div style=\"color: rgb(119, 119, 119); font-family: &quot;Open Sans&quot;, Arial, sans-serif; font-size: 14px; text-align: justify;\"><font size=\"4\" face=\"arial\" color=\"#000000\">Mejlisiniň meýdançasynda Türkmenistanyň Daşary işler ministriniň orunbasary bilen YHG-nyň Baş sekretary Asad Majid Hanyň arasynda gysga wagtlaýyn duşuşyk geçirildi. Taraplar Türkmenistan bilen YHG-nyň arasynda köptaraplaýyn hyzmatdaşlygyň ýagdaýy we geljegi barada pikir alyşdylar.</font></div>','habarlar/20250205/67a34ceb48613863.jpg',NULL,'2025-02-05 09:00:00',1,1,127,'2025-02-05 09:00:00','2026-10-28 18:20:26'),(13,'tm','Lukmançylyk mekdepleriniň bäsleşigi.','lukmanchylyk-mekdeplerinin-basleshigi','Türkmenistanyň Bilim ministrliginiň 2025-nji ýylyň 14-nji fewralyndaky 42 belgili buýrugy bilen tassyklanan: “Türkmenistanyň Bitaraplygynyň 30 ýyllygy hem-de 2025-nji ýylyň Birleşen Milletler Guramasynyň baş…','Türkmenistanyň Bilim ministrliginiň 2025-nji ýylyň 14-nji fewralyndaky  42 belgili  buýrugy bilen tassyklanan: “Türkmenistanyň Bitaraplygynyň 30 ýyllygy hem-de 2025-nji ýylyň Birleşen Milletler Guramasynyň baş Assambleýasy tarapyndan “Halkara parahatçylyk we ynanyşmak ýyly” diýilip yglan edilmegi mynasybetli, orta hünär okuw mekdepleri tarapyndan 2025-nji ýylda geçirmeli çäreleriň Meýilnamasynyň” çäklerinde, hem-de “Saglyk” Döwlet Maksatnamasynyň 30  ýyllygy mynasybetli, 2025-nji ýylyň  31-nji maýynda, I.Gandi  adyndaky  Aşgabat lukmançylyk  orta  okuw  mekdebinde  “Watana  wepam bar, kärime sarpam” atly, ýurdumyzyň  Lukmançylyk orta okuw mekdepleriniň  arasynda bilim bäsleşigi geçirildi. \r\nTalyp ýaşlar “Şepagatçylyk işi”  hem-de “Anatomiýa we fiziologiýa” derslerinden öz  bilim derejelerini, ukyp  başarnyklaryny we geljeki kärine bolan höweslerini, bilim almakda ylmy edebiýatlar bilen hem gyzyklanýandyklaryny, çylşyrymly testleri we şekilli ýumuşlary çözmekde tutanýerliligini, ýokary  taýýarlyklaryny görkezdiler.   \r\nBäsleşigiň netejeleri boýunça aşakdaky   ýeňijiler kesgitlendi:\r\n\r\n“Şepagatçylyk işi” dersi boýunça:\r\nI  orun -   I.Gandi adyndaky Aşgabat lukmançylyk orta okuw  mekdebi.\r\nII orun -  Gurbansoltan eje adyndaky Daşoguz lukmançylyk orta okuw mekdebi;\r\nS.A.Nyýazow adyndaky Mary lukmançylyk orta okuw mekdebi.\r\nIII orun- Türkmenabat  lukmançylyk orta okuw mekdebi;\r\nS.A.Nyýazow adyndaky Mary lukmançylyk orta okuw mekdebi.\r\n 	                      \r\n“Anatomiýa we fiziologiýa”  dersi boýunça:\r\n\r\nI  orun - S.A.Nyýazow adyndaky Mary lukmançylyk orta okuw mekdebi;\r\nTürkmenabat  lukmançylyk orta okuw mekdebi;\r\nBalkan lukmançylyk orta okuw mekdebi.\r\nII orun -  Saçly Dursunowa adyndaky Arkadag säher lukmançylyk orta hünär okuw    mekdebi;\r\nBalkan lukmançylyk orta okuw mekdebi;\r\nGurbansoltan eje adyndaky Daşoguz lukmançylyk orta okuw mekdebi.\r\nIII orun- I.Gandi adyndaky Aşgabat lukmançylyk orta okuw  mekdebi;\r\nGurbansoltan eje adyndaky Daşoguz lukmançylyk orta okuw mekdebi.\r\n\r\n\r\n     Bäsleşigiň  soňunda ýeňijilere  hormat hatlar we mynasyp  sowgatlar gowşuryldy.','habarlar/20250621/68566b4d6f37868.jpg',NULL,'2025-06-02 09:00:00',1,2,129,'2025-06-02 09:00:00','2026-10-28 18:20:21'),(14,'tm','“Parahatçylygyň ýaş çaparlary” - akyl-paýhas bäsleşigiň nobatdaky oýny suw diplomatiýasyna bagyşlanar','parahatchylygyn-yash-chaparlary-akyl-payhas-basleshigin-nobatdaky-oyny-suw-diplomatiyasyna-bagyshlanar','Suw serişdeleri we olardan netijeli peýdalanmak Merkezi Aziýanyň durnukly ösüşini üpjün etmekde ileri tutulýan ugurlaryň biridir. Şoňa görä-de, Türkmenistan iri forumlarda, şol sanda BMG-niň Baş Assambleýasynyň…','Suw serişdeleri we olardan netijeli peýdalanmak Merkezi Aziýanyň durnukly ösüşini üpjün etmekde ileri tutulýan ugurlaryň biridir. Şoňa görä-de, Türkmenistan iri forumlarda, şol sanda BMG-niň Baş Assambleýasynyň mejlislerinde, sammitlerinde birnäçe ahlumumy bähbitli başlangyçlary öňe sürýär.\r\n\r\nŞu nukdaýnazardan şeýle möhüm meselelere ýaşlaryň ünsüni çekmek hem örän wajyp bolup durýar. Şeýle maksatlardan ugur alnyp, TDIM-niň Halkara gatnaşyklary institutynyň garamagyndaky Ýaş diplomatlaryň mekdebiniň gurnamagynda ýokary synp mekdep okuwçylarynyň arasynda “Parahatçylygyň ýaş çaparlary” akyl-paýhas bäsleşiginiň «Bitarap Türkmenistanyň parahatçylygy dörediji diplomatiýasy: netijeli hyzmatdaşlygyň we durnukly ösüşiň ygtybarly guraly» atly şygar bilen geçirilýän IV möwsüminiň 7-nji saýlama oýnunyň “Türkmenistanyň suw diplomatiýasy: suw damjasy – altyn dänesi, goňşyň goňşa hormatynyň manysy” temasy boýunça geçirilýandigi habar berilýär.\r\n\r\nIV möwsüminiň 7-nji saýlama oýny 2025-nji ýylyň 26-njy martynda geçiriler.','habarlar/20250621/68566bec7037c314.jpg',NULL,'2025-03-10 09:00:00',1,1,130,'2025-03-10 09:00:00','2026-10-28 18:20:22'),(15,'tm','Halkara zenanlar güni mynasybetli baýramçylyk dabarasy geçirildi','halkara-zenanlar-guni-mynasybetli-bayramchylyk-dabarasy-gechirildi','8-nji martda Söwda-senagat edarasynda Halkara zenanlar güni mynasybetli berkarar Watanymyzyň ajaýyp gelin-gyzlarynyň hormatyna baýramçylyk dabarasy geçirildi. Oňa ýurdumyzyň ýolbaşçy düzüminiň, ministrlikleriň we…','8-nji martda Söwda-senagat edarasynda Halkara zenanlar güni mynasybetli berkarar Watanymyzyň ajaýyp gelin-gyzlarynyň hormatyna baýramçylyk dabarasy geçirildi. Oňa ýurdumyzyň ýolbaşçy düzüminiň, ministrlikleriň we pudaklaýyn dolandyryş edaralarynyň, köpçülikleýin habar beriş serişdeleriniň wekilleri gatnaşdylar. Dabaranyň hormatly myhmanlarynyň hatarynda köp çagaly eneler, jemgyýetçilik guramalarynyň işjeň agzalary, alymlar, medeniýet işgärleri, dürli ulgamlarda zähmet çekýän zenanlar, daşary döwletleriň we halkara guramalaryň ýurdumyzdaky diplomatik wekilhanalarynyň işgärleri bar.\r\n\r\nHormatly Prezidentimiz baýramçylyk mynasybetli ýurdumyzyň enelerine, ähli gelin-gyzlaryna iberen Gutlagynda Garaşsyz döwletimiziň hemişelik Bitaraplygynyň şanly 30 ýyllygynyň halkara derejede bellenilýän Halkara parahatçylyk we ynanyşmak ýylynda bu nurana baýrama bagyşlanyp, eziz Diýarymyzyň ähli obalarynda we şäherlerinde geçiriljek dabaralaryň göwünleri galkyndyryp, eziz Watanymyza söýgini, eşretli durmuşymyza, bagtyýar döwrümize buýsanjy has-da artdyrjakdygyna berk ynam bildirdi. “Türkmen zenany maşgalanyň sütünidir, ahlak gözelliginiň nusgasydyr, öý-ojaklarymyzyň ýaraşygydyr. Zenanlara sarpa goýmak, olaryň mertebesini belent tutmak gözbaşyny müňýyllyklardan alyp gaýdýan milli ýörelgelerimiz bolup, bu ajaýyp ýörelgeler bedew bady bilen ynamly öňe barýan demokratik, hukuk we dünýewi döwletimiziň deňsiz-taýsyz ösüşleri gazanýan Berkarar döwletiň täze eýýamynyň Galkynyşy döwründe mynasyp dowam etdirilýär” diýip, döwlet Baştutanymyz belledi.\r\n\r\nTäze taryhy döwürde Watanymyzyň ösüşlerine mynasyp goşant goşýan zähmetsöýer zenanlarymyz milli ahlak gymmatlyklarymyzy, däp-dessurlarymyzy gorap saklaýjylar hökmünde döwlet we jemgyýetçilik durmuşyna işjeň gatnaşýarlar. Olar dolandyryş edaralarynda, ykdysadyýetimiziň dürli pudaklarynda zähmet çekýärler, telekeçilik işini alyp barmak bilen, ata Watanymyzyň belent sepgitlere, üstünliklere ýetmegine, Gahryman Arkadagymyz tarapyndan başy başlanyp, häzirki wagtda hormatly Prezidentimiziň baştutanlygynda üstünlikli dowam etdirilýän oňyn özgertmeleriň amala aşyrylmagyna uly goşant goşýarlar.\r\n\r\nÝokary bilim we hünär derejesi, telekeçilik başlangyçlary häzirki zaman zenanlarynyň aýrylmaz häsiýetlerine öwrülýär. Ýurdumyzyň köp sanly zenanlary ýylyň-ýylyna döwlet sylaglary — ordendir medallar bilen sylaglanylýar. Halkara zenanlar gününiň öňüsyrasynda hem Türkmenistanyň Prezidenti köp çagaly enelere «Ene mähri» diýen hormatly ady dakmak hakynda Permana we ýurdumyzyň edara-kärhanalarynda zähmet çekýänlerden başlap, pensiýadaky enelere, mekdep okuwçylaryna, çagalar baglarynda terbiýelenýänlere çenli ähli gelin-gyzlara pul sowgatlaryny gowşurmak hakynda Buýruga gol çekdi. Döwlet Baştutanymyzyň tabşyrygy boýunça köp çagaly maşgalalara täze öýleriň açarlarynyň gowşurylmagy olaryň baýramçylyk şatlygyny has-da artdyrdy. Bu ajaýyp dabaralar halkymyzyň milli ruhy gymmatlyklarynyň mizemezliginiň, gadymdan gelýän mukaddesliklere, şol sanda öý-ojagyň diregi hasaplanýan enelerimiziň we zenanlarymyzyň hormatyny hemişe belentde tutmaga ygrarlydygynyň nyşany boldy. Olaryň ruhy-ahlak däplerimizi gorap saklamakda, sagdyn durmuş ýörelgelerini wagyz etmekde, ýaş nesilleri sazlaşykly terbiýelemekde eýeleýän orny bimöçberdir.\r\n\r\nEneleri we çagalary, maşgala gymmatlyklaryny goramak, zenanlaryň döredijilik, aň-paýhas mümkinçiliklerini ösdürmek baradaky aladalar çagalardyr zenanlaryň hukuklary babatda üstüne alan borçnamalaryna pugta ygrarly bolan Türkmenistanyň döwlet syýasatynyň ileri tutulýan ugurlarynyň biridir. Enäniň we çaganyň hukuklaryny goramak babatda anyk çäreler, olaryň saglygyny goramaga, çagalaryň doly derejede kemala gelmegine, köp çagaly maşgalalaryň durmuş taýdan goldanylmagyna gönükdirilen maksatnamalaryň üstünlikli durmuşa geçirilmegi we başga-da köp sanly işler bu syýasatda esasy orny eýeleýär. Döwletimiziň özleri baradaky aladasyny hemişe duýup ýaşaýan ýurdumyzyň zenanlary hemmetaraplaýyn goldawlar, maşgala ojaklaryndaky abadançylyk, saýlap alan ugurlarynda öz mümkinçiliklerini durmuşa geçirmek, çagalaryny gülläp ösýän abadan ýurtda terbiýelemek üçin döredilýän mümkinçilikler üçin hormatly Prezidentimize we Gahryman Arkadagymyza çuňňur hoşallyk bildirýärler.\r\n\r\n...Söwda-senagat edarasynda geçirilen dabara gatnaşyjylar tüýs ýürekden çykýan mähirli gutlaglaryň we döredijilik çykyşlarynyň şaýatlary boldular. Dabarada meşhur aýdymçylar, tans toparlary çykyş etdi. Konsert “Berkarar döwletiň bagtyýar zenanlary” atly edebi aýdym-sazly kompozisiýa bilen açyldy. Ony ýerine ýetirmäge meşhur aýdymçylar, Türkmenistanyň Döwlet hory we teatr artistleri gatnaşdylar. Bu çykyş arkaly türkmen zenanlarynyň gözelligi, olaryň hoşniýetlilik, päk ahlaklylyk, wepalylyk, mähremlik ýaly asylly häsiýetleri wasp edildi. Arkadagly Gahryman Serdarymyzyň belleýşi ýaly, bu häsiýetler gelin-gyzlarymyzyň keşbiniň aýrylmaz bölegidir.\r\n\r\n2025-nji ýylyň şygaryna bagyşlanan “Halkara parahatçylyk we ynanyşmak ýyly” atly aýdym tomaşaçylar üçin ajaýyp sowgat boldy. Onuň üsti bilen dünýäde parahatçylygy, dost-doganlygy berkitmek babatda türkmen halkynyň Milli Lideriniň asylly başlangyçlaryny mynasyp dowam etdirýän hormatly Prezidentimiziň giň gerimli işleri wasp edildi. Mälim bolşy ýaly, Türkmenistanyň başlangyjy boýunça BMG-niň Baş Assambleýasy 2025-nji ýyly «Halkara parahatçylyk we ynanyşmak ýyly» diýip yglan etmek hakynda Kararnamany biragyzdan kabul etdi. Munuň özi ýurdumyzyň ählumumy parahatçylygy, durnukly ösüşi üpjün etmäge gönükdirilen işleriniň ykrar edilýändiginiň aýdyň güwäsine öwrüldi.\r\n\r\n“Diýarymyň mähriban zenanlary” atly aýdym-sazly horeografik çykyş şowhunly el çarpyşmalar bilen garşylanyldy. Konsertde ajaýyp aýdym-sazlar, folklor çykyşlary, meşhurlyk gazanan we täze aýdymlar, nusgawy sazlar, daşary ýurtlaryň aýdym-sazlary, şol sanda italýan, iňlis, rus dillerindäki aýdymlar ýaňlandy. Munuň özi Halkara parahatçylyk we ynanyşmak ýylynyň 8-nji mart baýramyny giňden dabaralandyrýan dünýä bileleşigi bilen jebisleşmegiň özboluşly nyşanyna öwrüldi.\r\n\r\nKonsertde, hususan-da, ýigitler öz döredijilik ussatlyklaryny görkezdiler. Olaryň ýerine ýetirmeginde milli nusgawy saz eserleri, meşhur estrada we halk aýdymlary ýaňlanyp, olaryň hemmesi zenanlara bagyşlandy. Çykyşlarda zenan bagtynyň, wepalylygynyň, ene söýgüsiniň, mähriban topragyň ýaz aýlarynda aýratyn gözel görnüşe gelýän gözelliginiň waspy ýetirildi. Ähli çykyşlaryň wideogörnüşler bilen utgaşdyrylmagy konsertiň özüne çekijiligini has-da artdyrdy. Ýürekleri tolgundyrýan aýdym-sazlar joşgunly çykyşlar bilen dowam etdi. El çarpyşmalardyr baýramçylyk gutlaglary bilen utgaşan konsertde ýerine ýetirijiler belent ruha, hoşallyk duýgularyna, iň gowy arzuwlara beslenen aýdymlaryny mährem gyz-gelinlerimize bagyşladylar.\r\n\r\nDabara gatnaşyjylar milli sungatymyzyň aýrylmaz bölegi bolan «Küştdepdi» tansyny joşgunly el çarpyşmalar bilen garşyladylar.\r\n\r\nGahryman Arkadagymyzyň dabara sanly ulgam arkaly göni ýaýlymda gatnaşyp, mähriban zenanlarymyzy Halkara zenanlar güni bilen gutlamagy çäräniň esasy wakasyna öwrüldi. Milli Liderimiz dabara gatnaşyjylara ýüzlenip, eziz ene-mamalarymyzy, gelin-gyzlarymyzy, ähli zenanlary ýurdumyzda giňden bellenilýän Halkara zenanlar güni bilen tüýs ýürekden gutlady.\r\n\r\n“Biziň mähriban gelin-gyzlarymyz Watanymyzyň owadan gül-gunçalarydyr. Biziň gelin-gyzlarymyz öýlerimiziň bagt ýyldyzlarydyr. Türkmen halky ene-mamalarymyza, mähriban zenanlarymyza maşgala ojagynyň, maşgala abadançylygynyň eýesi hökmünde garap gelipdir. Mähriban zenanlarymyz, türkmeniň maşgala ojaklarynyň siziň bilen, siziň edep-terbiýäňiz bilen dowamat-dowamdygyny unutmaly dälsiňiz!” diýip, Gahryman Arkadagymyz aýtdy we maşgalanyň binýadyny berk saklamakda, çagalara mynasyp terbiýe bermekde, olary dogry durmuş ýoluna ugrukdyrmakda zenanlara örän uly ornuň degişlidigini belledi.\r\n\r\nMilli Liderimiz zenanlarymyzyň durmuşda göterýän ýüküniň, borjunyň asla ýeňil däldigine ünsi çekip, ata-babalarymyzyň, ene-mamalarymyzyň aňyrdan gelýän, inçeden sünnäläp bize ýetiren baý mirasyny, edep mekdebini, milli gymmatlyklaryny mundan beýläk-de dowam etdirmegiň zenanlara baglydygyny nygtady. “Şoňa görä-de, hemişe asylly däplerimizden ugur alyp, maşgala ojaklaryňyzyň bagtyýarlygyna guwanyp, gadyryny bilip ýaşamak size miýesser etsin! Pursatdan peýdalanyp, sizi ýene-de bir gezek ajaýyp bahar baýramyňyz bilen tüýs ýürekden gutlaýaryn. Goý, nurana ýüzli mähriban ene-mamalarymyzyň, bagtyýar gelin-gyzlarymyzyň, eziz uýalarymyzyň güler ýüzi hiç haçan solmasyn!” diýip, Gahryman Arkadagymyz arzuwlaryny beýan etdi.\r\n\r\nDabara gatnaşyjylar Milli Liderimiziň Gutlagyny we hoşniýetli arzuwlaryny şowhunly el çarpyşmalar bilen garşyladylar.\r\n\r\nBaýramçylyk dabarasy asylly häsiýetleri bilen dünýämizi bezeýän, oňa sazlaşyk, döredijilik şatlygyny bagyşlaýan ähli enelerimize, uýalarymyza, gyzlarymyza, zenanlarymyza bagtyýarlyk baradaky iň gowy arzuwlaryň nobatdaky beýanyna öwrülen “Bu bagtyýar Diýarda zenanlara sarpa bar” atly aýdym bilen jemlendi. Dabara gatnaşyjylar Watanymyzda amala aşyrylýan özgertmeler, abadan durmuşda ýaşamaga döredilýän şertler üçin hormatly Prezidentimize we Gahryman Arkadagymyza çäksiz hoşallyklaryny beýan etdiler.\r\n\r\n***\r\n\r\nHalkara zenanlar güni mynasybetli aýdym-sazly dabaralar ýurdumyzyň ähli künjeklerinde — paýtagtymyzyň, Arkadag şäheriniň, welaýatlaryň konsert merkezlerinde-de ýaýbaňlandyryldy. Kalby bahar pasly ýaly gözel zenanlarymyza bagyşlanan ajaýyp dabaraly çärelerde döredijiligiň we täze durmuşyň şatlygy aýdyň duýuldy.','habarlar/20250621/68566cb8f417e845.jpg',NULL,'2025-03-08 09:00:00',1,1,131,'2025-03-08 09:00:00','2026-10-28 18:20:23'),(16,'tm','Halkara zenanlar güni mynasybetli aýal-gyzlara pul sowgatlarynyň gowşurylyş dabarasy geçirildi','halkara-zenanlar-guni-mynasybetli-ayal-gyzlara-pul-sowgatlarynyn-gowshurylysh-dabarasy-gechirildi','2025-nji ýylyň 5-nji martynda Ýagşygeldi Kakaýew adyndaky Halkara nebit we gaz uniwersitetinde zähmet çekýän we okaýan gelin-gyzlara 8-nji mart – Halkara zenanlar güni mynasybetli Arkadagly Gahryman Serdarymyzyň adyndan…','2025-nji ýylyň 5-nji martynda Ýagşygeldi Kakaýew adyndaky Halkara nebit we gaz uniwersitetinde zähmet çekýän we okaýan gelin-gyzlara 8-nji mart – Halkara zenanlar güni mynasybetli Arkadagly Gahryman Serdarymyzyň adyndan pul sowgatlarynyň gowşurylyş dabarasy geçirildi.\r\n\r\nÝurdumyzyň gülläp ösmeginde we özgertmeleri amala aşyrmakda zenanlarymyzyň bitirýän uly hyzmatlaryny, Watanymyza wepaly, sagdyn we ruhubelent nesilleri terbiýeläp ýetişdirýändiklerini nazara alyp, şeýle hem ata-babalarymyzyň mähriban enelerimize we eziz uýalarymyza hormat goýmak baradaky asylly däplerini dowam etdirmek maksady bilen ýurdumyzyň dürli künjeklerinde asylly däbe öwrülen uly şowhunly baýramçylyklar geçirilýär.\r\n\r\nMilli Liderimiz Gahryman Arkadagymyzyň belleýşi ýaly, Enä tagzym etmek – mukaddeslige tagzym etmekdir. Şonuň üçin hem mähribanlygy we mylaýymlygy, wepalylygy we paýhasy, gözelligi we kämilligi özünde jemleýän türkmen zenanlaryna hormat, sarpa goýulmagy öz gözbaşyny gadymyýetden alyp gaýdýan mukaddeslikdir, hiç bir döwürde hem gadryny gaçyrmaýan gymmatly hazynadyr. \r\n\r\nDabaraly çäräniň ahyrynda gelin-gyzlar döwletimizde oňyn özgertmeleriň amala aşyrylýandygy, parahatçylygyň we döredijiligiň möhüm şerti bolan abadan durmuşyň üpjün edilmegi ugrunda zerur şertleriň döredilýändigi üçin hormatly Prezidentimize sagbolsun aýtdylar. ','habarlar/20250621/68566d315b7a7801.jpg',NULL,'2025-03-07 09:00:00',1,1,132,'2025-03-07 09:00:00','2026-10-28 18:20:24'),(17,'tm','«Halkara parahatçylyk we ynanyşmak ýylyna» bagyşlanylan dabaraly maslahat geçirildi','halkara-parahatchylyk-we-ynanyshmak-yylyna-bagyshlanylan-dabaraly-maslahat-gechirildi','Fewral aýynyň 24-ne Türkmenistanyň Magtymguly adyndaky milli sazly drama teatrynda aýdym-sazly dabaraly maslahat geçirildi. Ýurdumyzyň döredijilik, medeniýet işgärleriniň, žurnalistleriň, sungat ussatlarynyň, meşhur…','Fewral aýynyň 24-ne Türkmenistanyň Magtymguly adyndaky milli sazly drama teatrynda aýdym-sazly dabaraly maslahat geçirildi.\r\n\r\nÝurdumyzyň döredijilik, medeniýet işgärleriniň, žurnalistleriň, sungat ussatlarynyň, meşhur aýdymçylaryň we talyp ýaşlaryň gatnaşmagynda geçirilen dabaraly maslahat Türkmenistanyň hemişelik Bitaraplygynyň şanly 30 ýyllygyny mynasyp dabaralandyrmak babatda türkmen halkynyň Milli Lideri, Gahryman Arkadagymyzyň we hormatly Prezidentimiziň beren tabşyryklarynyň ýerine ýetirilmegine hem-de «Halkara parahatçylyk we ynanyşmak ýylyna» bagyşlandy.\r\n\r\nDabaraly maslahat «Halkara parahatçylyk we ynanyşmak ýylyna» bagyşlanylan aýdym-sazly çykyş bilen başlanyldy. Soňa onda çykyş edenler türkmen halkynyň Milli Lideri, Halk Maslatynyň Başlygy Gurbanguly Berdimuhamedowyň Ministrler Kabinetiniň agzalarynyň gatnaşmagynda Türkmenistanyň Bitaraplygynyň 30 ýyllyk şanly senesini ýokary derejede dabaralandyrmak boýunça geçiren maslahatynda öňe süren başlangyçlarynyň ähmiýeti barada aýdyp, şanly senäniň ýurdumyzyň we jemgyýetimiziň durmuşynda möhüm orun eýeleýändigini, onuň ýurdumyzyň parahatçylyk söýüjilikli syýasatynyň rowaçlanmagyna giň ýol açýandygyny bellediler.\r\n\r\nGahryman Arkadagymyz baýramçylyk dabaralaryna taýýarlygyň çäklerinde halkara derejesinde geçiriljek maslahatlaryň ýurdumyzyň parahatçylyk söýüjilikli daşary syýasat strategiýasynyň ýörelgelerine laýyk gelmelidigini belledi. Aýratyn-da, baýramçylyk mynasybetli geçiriljek halkara forumlar ýurdumyzyň ynsanperwer ýörelgeleri esasy ugur edinýän bitaraplyk derejesine laýyklykda guralmalydyr. Munuň özi ýurdumyzda durmuşa geçirilýän daşary syýasatynyň talaplaryna doly laýyk gelmelidir. Şol bir wagtyň özünde bu çäreleriň köpçülikleýin habar beriş serişdeleriniň wekilleri tarapyndan beýan edilmegine zerur üns berilmelidir.\r\n\r\nŞoňa görä-de, dabaraly maslahatda çykyş edenler bu ugurda alyp barýan işlerinde 2025-nji ýylyň “Halkara parahatçylyk we ynanyşmak ýyly” şygarynyň mazmunyna laýyklykda we hormatly Prezidentimiziň we Gahryman Arkadagymyzyň bu ugurda öňde goýan wezipelerini üstünlikli berjaý etmek ugurnda ähli ukyp-başarnyklaryny gaýgyrman işlejekdiklerine ynandyrdylar.\r\n\r\nDabaraly maslahatyň dowamynda aýdym-sazly çykyşlar bilen utgaşyp onuň many-mazmunyny artdyrdy.','habarlar/20250621/68566e9f340a1512.jpg',NULL,'2025-02-25 09:00:00',1,1,133,'2025-02-25 09:00:00','2026-10-28 18:20:26'),(18,'tm','2025/2026-njy okuw ýyly üçin aşakdaky hünärler boýunça talyplyga kabul edýär:','2025-2026-njy-okuw-yyly-uchin-ashakdaky-hunarler-boyuncha-talyplyga-kabul-edyar','SAÇLY DURSUNOWA ADYNDAKY ARKADAG SÄHER LUKMANÇYLYK ORTA HÜNÄR OKUW MEKDEBI 2025/2026-njy okuw ýyly üçin aşakdaky hünärler boyunça talyplyga kabul edýär: Byujet esasynda: 1. Şepagatçylyk işi 2. Laboratoriýa anyklaýyş işi…','SAÇLY DURSUNOWA ADYNDAKY ARKADAG SÄHER\r\nLUKMANÇYLYK ORTA HÜNÄR OKUW MEKDEBI\r\n2025/2026-njy okuw ýyly üçin aşakdaky\r\nhünärler boyunça talyplyga kabul edýär:\r\n\r\n \r\nByujet esasynda:\r\n1.	Şepagatçylyk işi\r\n2.	Laboratoriýa anyklaýyş işi\r\n3.	Bejeriş işi.\r\n4.	Saglygy goraýyş-öňüni alyş işi.\r\n5.	Farmasiýa\r\nSaçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebine Arkadag şäherinde we Ahal welaýatynda hemişelik ýaşaýan, umumy orta bilimden pes bolmadyk binýatda bilimi bolan, ýaşy 35-den geçmedik Türkmenistanyň rayatlary giriş sy- naglarynyň netijeleri boyunça bäsleşik esa¬synda okuwa kabul ediyär.\r\nResmi iş kagyzlary: Arkadag şäherinde (Arkadag şaheri we Ahal welaýaty boýunça 2025-nji yytyň 14 — 27-np iyuly aralygynda kabul edilýar.\r\nResmi iş kagyzlarynyň sanawy:\r\n— bellenilen nusgada direktoryň adyna ýazylan arza,\r\n—	bellenilen nusgadaky sowalnama \r\n(anketa).\r\n—	bilimi baradaky resminama (asyl nus- gasy);\r\n—	Türkmenistanyň Saglygy goraýyş we derman senagaty ministrligi tarapyndan bel- lenilen nusgadaky saglyk kepilnamasy;\r\n—	soňky okan ýerinden (işlän ýerinden, harbv bölümden) häsiýetnama;\r\n—	3x4 sm ölçegdäki sekiz sany fotosurat;\r\n—	işleyänler üçin zähmet depderçesiniň tassyklanan göçürmesi:\r\n— okuw dersleri boýunça mekdep okuw- çylarynyň döwtet bäsleşiginiň ýeňijileri. halkara bäsleşiklere gatnaşan Türkmenistanyň ýygyndy toparynyň agzalary şol ýagdaýlary tassykaýan degişli resminamanyň asyl nusgasyny tabşyryar.\r\nBulardan başga-da. okuwa girmäge isteg bildirýänler ýokarda görkezilen resminamalar bilen birlikde. resminamalary kabul edyän iş toparyna aşakdakylary görkezyärler we nus- galaryny tabşyrýarlar.\r\n— pasportyny.\r\n— harby şahadatnamasyny ya-da harby hasaba goylandygy hakynda şahadatnama- syny.\r\nDalaşgär bäsleşiksiz we (ya-da) okuwa kabul edilmek üçin artykmaç hukukdan peý- dalanýandygyny tassyklaýan beýleki resmi-namalary görkezip biler.\r\nNädogry berilen maglumatlar we galp res¬mi iş kagyzlary üçin dalaşgär şahsy jogap-kärçilik çekyär.\r\nGiriş synaglary we okuwa kabul edilmek Saçty Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde (Arkadag ş.) 2025-nji yylyň iýul ayynyň 30-31-i, awgust ayynyň 2-3-i we 5-i günlerinde geçirilyär.\r\nGiriş synaglary ähli hunärler boýunça himiya, bioiogiya. Türkmenislanyň taryhy derslerinden geçirilyär.\r\nOkuw dersleri boyunça giriş synaglary Türkmenistanyň orta mekdepleriniň okuw maksatnamalarynyň esasynda. döwlet dilin¬de dilden geçirilyär\r\nSaýlap alan hünärine durnuklydygyny kesgittemek maksady bilen, dalaşgärler pa- tologoanatomik edaranyň işi bilen tanyşdyrylar.\r\nGiriş synaglarynyň teribinde bellenilen wagtda synaglara esassyz sebäplere görä gelip bimedikler ýa-da okuw dersleriniň biri boýunça synagdan geçip bilmedikler soňky synaglara göýberilmeyar\r\nGiriş synaglaryndan üstünlikli geçen ýag- daýynda, bäsleşiksiz we talyplyga kabul edilmek üçin artykmaç hukukdan «Bilim hakynda» Türkmenistanyň Kanunynyň rejelenen gönüşinde kesgitlenen düzgünlere laýyk gelýän dalaşgärler peýdalanýarlar\r\nSaçly Dursunowa adyndaky\r\nArkadag şäher lukmançylyk orta\r\nhünär okuw mekdebiniň salgysy:\r\nArkadag şäheri,\r\nArkadag şaýoly. 22,\r\ntel.: 57-20-21. 57-20-22.\r\n','habarlar/20250714/6874f990b43c1184.jpg',NULL,'2025-07-01 09:00:00',1,1,134,'2025-07-01 09:00:00','2026-10-28 18:20:20'),(19,'tm','WAGYZ-NESIHAT ÇÄRELERI','wagyz-nesihat-chareleri','07.08.2025 senede “Arkadag” teleýaýlymynyň Arkadag şäheriniň Aman Gulmämmedow adyndaky döwlet drama teatryndaky studiýasynda Türkmenistanyň Magtymguly adyndaky ýaşlar guramasynyň Arkadag şäher Geňeşliginiň başlygynyň…','07.08.2025 senede “Arkadag” teleýaýlymynyň Arkadag şäheriniň Aman Gulmämmedow adyndaky döwlet drama teatryndaky studiýasynda Türkmenistanyň Magtymguly adyndaky ýaşlar guramasynyň Arkadag şäher Geňeşliginiň başlygynyň orunbasary Beýzaly we Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiniň mugallymy, KAIG-yň başlygy Alparslan Baýramowyň gatnaşmagynda Berkarar döwletiň täze eýýamynyň Galkynyşy döwründe Gahryman Arkadagymyzyň, Arkadagly Gahryman Serdarymyzyň ýolbaşçylygynda üstünlikli durmuşa geçirilýän syýasatyny wagyz etmek maksady bilen geçirilen tegelek stoluň başyndaky söhbetdeşlik.\r\n','habarlar/20250902/68b6ccf4538a560.jpg',NULL,'2025-08-28 09:00:00',1,1,135,'2025-08-28 09:00:00','2026-10-28 18:20:20'),(20,'tm','“Bilimler  we talyp ýaşlar güni” dabaraly pursady.','bilimler-we-talyp-yashlar-guni-dabaraly-pursady','1-nji sentýabrda ýurdumyzyň ähli bilim edaralarynda 2025-2026-njy täze okuw ýylynyň başlanýandygyny alamatlandyrýan ilkinji jaň kakyldy. Asylly däbe görä, täze okuw ýylynyň ilkinji güni Garaşsyzlyk binasyna we…','1-nji sentýabrda ýurdumyzyň ähli bilim edaralarynda 2025-2026-njy täze okuw ýylynyň başlanýandygyny alamatlandyrýan ilkinji jaň kakyldy.\r\nAsylly däbe görä, täze okuw ýylynyň ilkinji güni Garaşsyzlyk binasyna we Berdimuhamet Annaýew adyndaky Arkadag şäher mugallymçylyk orta hünär okuw mekdebindäki hem-de Ahal welaýatynyň Gökdepe etrabynyň Yzgant şäherçesindäki 27-nji orta mekdepde ýerleşýän Berdimuhamet Annaýewiň ýadygärliklerine gül goýmak bilen başlandy. Bilimler we talyp ýaşlar gününde ähli orta hem ýokary okuw mekdeplerinde dabaraly nyzamlar geçirilip, olarda hormatly Prezidentimiz Serdar Berdimuhamedowyň Gutlagy okaldy. Şunlukda, döwlet Baştutanymyz ýaş nesillere bilimleriň, uly açyşlaryň ýoluna ak pata berdi. Ýurdumyzda täze okuw ýylynyň ilkinji sapagy “Pähim-paýhas ummany Magtymguly Pyragy” ýylyna hem-de ýetip gelýän şanly senä — mukaddes Garaşsyzlygymyzyň 33 ýyllygyna bagyşlandy.Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebinde “Bilimler we talyp ýaşlar güni” mynasybetli geçiriljek dabaraly çäresi geçirildi. Irdenki çärede 2-nji ýyl talyplar 1-nji ýyl talyplara bilimler ummanyň açaryny hem-de talyplyk şahadatnamasynyň nusgasyny gowşurmagy we 1-nji ýyl talyplaryň Türkmenistanyň Ýaşyl Tuguny togap edip, okuw binasynyň gapysyndan girdiler.\r\n','habarlar/20250902/68b6cec5d5804278.jpg',NULL,'2025-09-01 08:00:00',1,1,136,'2025-09-01 08:00:00','2026-10-28 18:20:20'),(21,'tm','Saçly Dursunowanyň ömür döredijiligi bilen tanyşdyrylyş dabarasy.','sachly-dursunowanyn-omur-doredijiligi-bilen-tanyshdyrylysh-dabarasy','Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiň mejlisler zalynda mugallymlaryň we I ýyl talyplaryň gatnaşmagynda Gahryman zenan, ussat lukman Saçly Dursunowanyň ömür döredijiligi bilen…','Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiň mejlisler zalynda mugallymlaryň we I ýyl talyplaryň gatnaşmagynda Gahryman zenan, ussat lukman Saçly Dursunowanyň ömür döredijiligi bilen tanyşdyrylyş dabarasy. \r\nSaçly Dursunowa 1918-nji ýylda dünýä inip, çagalygyndan ýetim galýar. 1925-nji ýylda ýaňy ýedi ýaşyny dolduran Saçlyny özünden bir ýaş uly gyz dogany Çeper bilen bir ýaş ýigit Aşgabadyň çagalar öýüne alyp gelýär. Büzmeýinde bu ýetim galan çagalara hossarlyk edip, olary çagalar öýüne getiren ýaş ýigit soň-soňlar meşhur ýazyjy bolup ýetişen Ata Gowşudowdy. Bu iki çaganyň öz kakalarynyň atlaryny bilmändikleri üçin ejeleriniň ady bilen «Çeper Dursun gyzy» we «Saçly Dursun gyzy» diýip resminamalar doldurylýar.\r\n\r\n1932-nji ýylda Aşgabadyň ozalky Lukmançylyk tehnikumyna okuwa girip, ony tapawutlanan bahalar bilen 1936-njy ýylda tamamlan Saçly şol wagtky Türkmen döwlet medisina institutyna girýär. Onuň soňky gutardyş synaglary galanda nägehan uruş başlanýar, okuwyny tamamlan ýyly bolsa, Garrygala (häzirki Magtymguly) şäherçesine işe ugradylýar. Emma uruşdaky ýaralylara ýardam etmek maksady bilen, ol fronta gitmeli diýen gutarnykly netijä gelýär. 1942-nji ýylyň aprel aýynda Saçly Dursunowa Stalingradyň eteginde söweş alyp barýan 62-nji atyjylyk diwiziýasynyň 534-nji medisina sanitar batalýonynda ordinator-lukman bolup harby gulluga başlaýar. Ol bütin urşuň dowamynda Krymyň, Belorussiýanyň, Pribaltika ýurtlarynyň, Gündogar Prussiýanyň çäklerinde bolan söweş hereketleriniň janly şaýady bolýar, şol ýerlerde ýaraly esgerlere hem ruhy tarapdan, hem lukmançylyk tarapdan yzygiderli ýardam edýär. Şeýdibem, ýeňşiň gazanylmagyna özüniň uly goşandyny goşýar. Görkezen edermenlikleri üçin gahryman zenan «Lenin», «Gyzyl ýyldyz», «Hormat nyşany» ordenleri, «Edermenligi üçin», «Söweşjeň hyzmatlary üçin», «Stalingradyň azat edilendigi üçin», «Kýonigsbergiň eýelendigi üçin», «Germaniýanyň üstünden gazanylan ýeňiş üçin» medallary bilen sylaglanýar. ','habarlar/20250902/68b6d231ca7fe777.jpg',NULL,'2025-09-01 11:00:00',1,1,137,'2025-09-01 11:00:00','2026-10-28 18:20:19'),(22,'tm','«ÝoI hereketiniň howpsuzlygy - ömrümiziň rahatlygy»','yoi-hereketinin-howpsuzlygy-omrumizin-rahatlygy','Berkarar döwletiň täze eýýamynyň Galkynyşy döwründe 2025-nji - HaIkara parahatçylyk we ynanyşmak ýylynyň sentýabr aýynyň dowamynda «ÝoI hereketiniň howpsuzlygy - ömrümiziň rahatlygy» atly biraýlygyň çäklerinde Arkadag…','Berkarar döwletiň täze eýýamynyň Galkynyşy döwründe 2025-nji - HaIkara parahatçylyk we ynanyşmak ýylynyň sentýabr aýynyň dowamynda «ÝoI hereketiniň howpsuzlygy - ömrümiziň rahatlygy» atly biraýlygyň çäklerinde Arkadag şäheriniň prokuraturasynyň, Arkadag şäheriniň Kazyýetiniň, Arkadag şäher Polisiýa müdirliginiň, Arkadag şäheriniň Migrasiýa gullugynyň, Türkmenistanyň Kärdeşler arkalaşyklarynyň Arkadag şäheriniň birleşmesiniň, Arkadag şäher Saglygy goraýyş müdirliginiň, Türkmenistanyň Magtymguly adyndaky Ýaşlar guramasynyň Arkadag şäheriniň Geňeşiniň wekilleri we Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiniň mugallymlarynyň we talyplarynyň gatnaşmagynda wagyz-nesihat çäresi geçirildi.','habarlar/20250904/68b96bbfbe582364.jpg',NULL,'2025-09-06 09:00:00',1,3,138,'2025-09-06 09:00:00','2026-10-29 10:06:14'),(23,'tm','“Türkmenistan – Halkara parahatçylygyň we dost doganlygyň mekany”','turkmenistan-halkara-parahatchylygyn-we-dost-doganlygyn-mekany','“Arkadag” teleýaýlymynyň ýazgy etmeginde ýurdumyzda “2025-nji ýyl – Halkara parahatçylyk we ynanyşmak ýyly” diýip yglan edilmegi mynasybetli Döwletmämmet Azady adyndaky Arkadag şäher kitaphanasy we Saçly Dursunowa…','<span lang=\"TK\" style=\"font-size:11.0pt;line-height:\r\n115%;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;\r\nmso-fareast-theme-font:minor-latin;letter-spacing:.4pt;mso-ansi-language:TK;\r\nmso-fareast-language:EN-US;mso-bidi-language:AR-SA\">“Arkadag” teleýaýlymynyň\r\nýazgy etmeginde ýurdumyzda “2025-nji ýyl – Halkara parahatçylyk we ynanyşmak\r\nýyly” diýip yglan edilmegi mynasybetli Döwletmämmet Azady adyndaky Arkadag\r\nşäher kitaphanasy we Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta\r\nhünär okuw mekdebi bilen bilelikde gurnamagynda “Türkmenistan – Halkara\r\nparahatçylygyň we dost doganlygyň mekany” atly göçme sergisi geçirildi.&nbsp;&nbsp;</span>','habarlar/20251025/68fc47e42c6ed966.jpg',NULL,'2025-10-20 09:00:00',1,1,139,'2025-10-20 09:00:00','2026-10-28 18:20:19'),(24,'tm','“Saglygym baş baýlygym”','saglygym-bash-baylygym','Türkmenistanyň Magtymguly adyndaky Ýaşlar guramasynyň Arkadag şäher Geňeşiniň we Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiniň bilikde gurnamagynda Türkmenistanyň Saglygy goraýyş we…','<span lang=\"TK\" style=\"font-size:12.0pt;mso-bidi-font-size:\r\n14.0pt;line-height:115%;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\r\nCalibri;mso-fareast-theme-font:minor-latin;letter-spacing:.4pt;mso-ansi-language:\r\nTK;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\">Türkmenistanyň\r\nMagtymguly adyndaky Ýaşlar guramasynyň Arkadag şäher Geňeşiniň we Saçly\r\nDursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebiniň bilikde\r\ngurnamagynda Türkmenistanyň Saglygy goraýyş we derman senagaty işgärleriniň\r\ngüni mynasybetli “Saglygym baş baýlygym” ady bilen “tegelek stoluň”\r\nbaşyndaky söhbetdeşlik guraldy.</span>','habarlar/20251025/68fc4bf05be9d351.jpg',NULL,'2025-10-08 09:00:00',1,1,140,'2025-10-08 09:00:00','2026-10-28 18:20:19'),(25,'tm','Tegelek stoluň başyndaky söhbetdeşlik.','tegelek-stolun-bashyndaky-sohbetdeshlik','2025-nji ýylyň 20 - nji sentýabrynda Saçly Dursunowa adyndaky Arkadag şäher lukmançylyk orta hünär okuw mekdebi nde « Arkadag » gazetiniň , Türkmenistanyň Magtymguly adyndaky ýaşlar guramasynyň 